use clap::{Parser, ArgAction};

#[derive(Parser, Debug, Clone)]
#[command(name = "dirble")]
#[command(about = "Fast directory scanning and scraping tool")]
#[command(version = "1.4.2 (commit d520c82, build 2026-04-17)")]
pub struct GlobalOpts {
    /// The URI of the host to scan, optionally supports basic auth with http://user:pass@host:port
    #[arg(value_name = "uri")]
    pub uri_positional: Option<String>,

    /// Additional hosts to scan
    #[arg(short = 'u', long = "uri", value_name = "uri", visible_alias = "url", action = ArgAction::Append)]
    pub uri: Vec<String>,

    /// The filename of a file containing a list of URIs to scan
    #[arg(short = 'U', long = "uri-file", value_name = "uri-file", visible_alias = "url-file")]
    pub uri_file: Option<String>,

    /// Specify which HTTP verb to use
    #[arg(long = "verb", value_name = "http_verb", default_value = "get")]
    pub verb: String,

    /// Sets which wordlist to use
    #[arg(short = 'w', long = "wordlist", value_name = "wordlist")]
    pub wordlist: Option<String>,

    /// Provides comma separated prefixes to extend queries with
    #[arg(short = 'p', long = "prefixes", value_name = "prefixes", num_args = 1.., value_delimiter = ',', action = ArgAction::Append)]
    pub prefixes: Vec<String>,

    /// The name of a file containing prefixes to extend queries with
    #[arg(short = 'P', long = "prefix-file", value_name = "prefix-file")]
    pub prefix_file: Option<String>,

    /// Provides comma separated extensions to extend queries with
    #[arg(short = 'x', long = "extensions", value_name = "extensions", num_args = 1.., value_delimiter = ',', action = ArgAction::Append)]
    pub extensions: Vec<String>,

    /// The name of a file containing extensions to extend queries with
    #[arg(short = 'X', long = "extension-file", value_name = "extension-file")]
    pub extension_file: Option<String>,

    /// Indicates whether the string "%EXT%" should be substituted with the current extension
    #[arg(long = "ext-sub")]
    pub ext_sub: bool,

    /// Only scan with provided extensions
    #[arg(short = 'f', long = "force-extension")]
    pub force_extension: bool,

    /// Ignore the certificate validity for HTTPS
    #[arg(short = 'k', long = "ignore-cert")]
    pub ignore_cert: bool,

    /// Enable display of items containing .ht when they return 403 responses
    #[arg(long = "show-htaccess")]
    pub show_htaccess: bool,

    /// Maximum time to wait for a response before giving up, in seconds
    #[arg(long = "timeout", value_name = "timeout", default_value = "5")]
    pub timeout: u64,

    /// The number of consecutive errors a thread can have before it exits
    #[arg(long = "max-errors", value_name = "max_errors", default_value = "5")]
    pub max_errors: u32,

    /// Sets a file to write JSON output to
    #[arg(long = "json-file", value_name = "json_file", visible_alias = "oJ")]
    pub json_file: Option<String>,

    /// Disable coloring of terminal output
    #[arg(long = "no-color")]
    pub no_color: bool,

    /// Sets the file to write the report to
    #[arg(short = 'o', long = "output-file", value_name = "output_file", visible_alias = "oN")]
    pub output_file: Option<String>,

    /// Sets a file to write XML output to
    #[arg(long = "xml-file", value_name = "xml_file", visible_alias = "oX")]
    pub xml_file: Option<String>,

    /// Specify length ranges to hide
    #[arg(long = "hide-lengths", value_name = "length_blacklist", num_args = 1.., value_delimiter = ',', action = ArgAction::Append)]
    pub hide_lengths: Vec<String>,

    /// Stores all output types
    #[arg(long = "output-all", value_name = "output_all", visible_alias = "oA")]
    pub output_all: Option<String>,

    /// Sets the proxy to use the default burp proxy values
    #[arg(long = "burp")]
    pub burp: bool,

    /// Disables proxy use
    #[arg(long = "no-proxy")]
    pub no_proxy: bool,

    /// The proxy address to use
    #[arg(long = "proxy", value_name = "proxy")]
    pub proxy: Option<String>,

    /// Sets the maximum number of request threads
    #[arg(short = 't', long = "max-threads", value_name = "max-threads", default_value = "10")]
    pub max_threads: usize,

    /// The number of threads to run for each folder/extension combo
    #[arg(short = 'T', long = "wordlist-split", value_name = "wordlist_split", default_value = "3")]
    pub wordlist_split: usize,

    /// Time each thread will wait between requests in milliseconds
    #[arg(short = 'z', long = "throttle", value_name = "milliseconds")]
    pub throttle: Option<u64>,

    /// Sets the username to authenticate with
    #[arg(long = "username", value_name = "username")]
    pub username: Option<String>,

    /// Sets the password to authenticate with
    #[arg(long = "password", value_name = "password")]
    pub password: Option<String>,

    /// Scan listable directories
    #[arg(short = 'l', long = "scan-listable")]
    pub scan_listable: bool,

    /// Sets the maximum directory depth to recurse to
    #[arg(long = "max-recursion-depth", value_name = "max_recursion_depth")]
    pub max_recursion_depth: Option<u32>,

    /// Disable discovered subdirectory scanning
    #[arg(short = 'r', long = "disable-recursion")]
    pub disable_recursion: bool,

    /// Enable scraping of listable directories for urls
    #[arg(long = "scrape-listable")]
    pub scrape_listable: bool,

    /// Set the user-agent provided with requests
    #[arg(short = 'a', long = "user-agent", value_name = "user_agent")]
    pub user_agent: Option<String>,

    /// Provide a cookie
    #[arg(short = 'c', long = "cookie", value_name = "cookie", action = ArgAction::Append)]
    pub cookies: Vec<String>,

    /// Provide an arbitrary header
    #[arg(short = 'H', long = "header", value_name = "header", action = ArgAction::Append)]
    pub headers: Vec<String>,

    /// Don't output information during the scan
    #[arg(short = 'S', long = "silent")]
    pub silent: bool,

    /// Increase the verbosity level
    #[arg(short = 'v', long = "verbose", action = ArgAction::Count)]
    pub verbose: u8,

    /// Provide a comma separated list of response codes to not show
    #[arg(short = 'B', long = "code-blacklist", value_name = "code_blacklist", num_args = 1.., value_delimiter = ',', action = ArgAction::Append)]
    pub code_blacklist: Vec<String>,

    /// Disable automatic detection of not found codes
    #[arg(long = "disable-validator")]
    pub disable_validator: bool,

    /// Provide a comma separated list of response codes to show
    #[arg(short = 'W', long = "code-whitelist", value_name = "code_whitelist", num_args = 1.., value_delimiter = ',', action = ArgAction::Append)]
    pub code_whitelist: Vec<String>,

    /// Scan folders even if they return 401 frequently
    #[arg(long = "scan-401")]
    pub scan_401: bool,

    /// Scan folders if they return 403 frequently
    #[arg(long = "scan-403")]
    pub scan_403: bool,
}

impl GlobalOpts {
    pub fn get_uris(&self) -> Vec<String> {
        let mut uris = Vec::new();
        if let Some(ref u) = self.uri_positional {
            uris.push(u.clone());
        }
        for u in &self.uri {
            uris.push(u.clone());
        }
        uris
    }

    pub fn get_code_blacklist(&self) -> Vec<u16> {
        self.code_blacklist.iter()
            .filter_map(|s| s.parse::<u16>().ok())
            .collect()
    }

    pub fn get_code_whitelist(&self) -> Vec<u16> {
        self.code_whitelist.iter()
            .filter_map(|s| s.parse::<u16>().ok())
            .collect()
    }

    pub fn get_hide_lengths(&self) -> Vec<(u64, u64)> {
        let mut ranges = Vec::new();
        for s in &self.hide_lengths {
            if s.contains('-') {
                let parts: Vec<&str> = s.splitn(2, '-').collect();
                if parts.len() == 2 {
                    if let (Ok(lo), Ok(hi)) = (parts[0].parse::<u64>(), parts[1].parse::<u64>()) {
                        ranges.push((lo, hi));
                    }
                }
            } else if let Ok(n) = s.parse::<u64>() {
                ranges.push((n, n));
            }
        }
        ranges
    }
}

pub fn get_args() -> GlobalOpts {
    GlobalOpts::parse()
}
EOF

