use std::fs::File;
use std::io::{BufRead, BufReader};

pub fn load_wordlist(filename: &str) -> Vec<String> {
    let file = match File::open(filename) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("[ERROR] Failed to open wordlist '{}': {}", filename, e);
            std::process::exit(1);
        }
    };

    let reader = BufReader::new(file);
    let mut words = Vec::new();

    for line in reader.lines() {
        match line {
            Ok(word) => {
                let word = word.trim().to_string();
                if !word.is_empty() {
                    words.push(word);
                }
            }
            Err(_) => {}
        }
    }

    words
}

pub fn load_list_file(filename: &str) -> Vec<String> {
    load_wordlist(filename)
}
