use url::Url;

/// Normalize a URI to ensure it ends with "/"
pub fn normalize_url(uri: &str) -> String {
    // If the URI has a path component that doesn't end with /,
    // we strip the last path component to get the parent directory
    let base = if uri.ends_with('/') {
        uri.to_string()
    } else {
        // Parse and get parent
        match Url::parse(uri) {
            Ok(mut u) => {
                let path = u.path().to_string();
                if path == "/" || path.is_empty() {
                    // It's just the root
                    if !uri.ends_with('/') {
                        format!("{}/", uri)
                    } else {
                        uri.to_string()
                    }
                } else {
                    // Strip the last component
                    let parent = if let Some(pos) = path.rfind('/') {
                        &path[..pos + 1]
