use reqwest::blocking::{Client, ClientBuilder, Response};
use reqwest::header::{HeaderMap, HeaderName, HeaderValue, COOKIE, USER_AGENT};
use reqwest::Proxy;
use std::time::Duration;
use std::str::FromStr;
use url::Url;

use crate::arg_parse::GlobalOpts;

#[derive(Debug, Clone)]
pub struct RequestConfig {
    pub timeout: Duration,
    pub max_errors: u32,
    pub verb: String,
    pub user_agent: Option<String>,
    pub cookies: Vec<String>,
    pub headers: Vec<String>,
    pub proxy: Option<String>,
    pub no_proxy: bool,
    pub ignore_cert: bool,
    pub throttle: Option<u64>,
    pub username: Option<String>,
    pub password: Option<String>,
}

impl RequestConfig {
    pub fn from_opts(opts: &GlobalOpts) -> Self {
        let proxy = if opts.burp {
            Some("http://localhost:8080".to_string())
        } else {
            opts.proxy.clone()
        };

        RequestConfig {
            timeout: Duration::from_secs(opts.timeout),
            max_errors: opts.max_errors,
            verb: opts.verb.clone(),
            user_agent: opts.user_agent.clone(),
            cookies: opts.cookies.clone(),
            headers: opts.headers.clone(),
            proxy,
            no_proxy: opts.no_proxy,
            ignore_cert: opts.ignore_cert,
            throttle: opts.throttle,
            username: opts.username.clone(),
            password: opts.password.clone(),
        }
    }
}

pub struct RequestClient {
    client: Client,
    pub config: RequestConfig,
}

#[derive(Debug, Clone)]
pub struct RequestResponse {
    pub url: String,
    pub code: u16,
    pub content_len: u64,
    pub redirect_url: String,
    pub body: Option<String>,
}

impl RequestClient {
    pub fn new(config: RequestConfig) -> Self {
        let mut builder = ClientBuilder::new()
            .timeout(config.timeout)
            .danger_accept_invalid_certs(config.ignore_cert)
            .redirect(reqwest::redirect::Policy::none());

        if config.no_proxy {
            builder = builder.no_proxy();
        } else if let Some(ref proxy_url) = config.proxy {
            if let Ok(proxy) = Proxy::all(proxy_url) {
                builder = builder.proxy(proxy);
            }
        }

        let client = builder.build().expect("Failed to build HTTP client");

        RequestClient { client, config }
    }

    pub fn request(&self, url: &str, get_body: bool) -> Option<RequestResponse> {
        log::trace!("[src/request.rs:114] Requesting {}", url);

        // Apply throttle if configured
        if let Some(ms) = self.config.throttle {
            std::thread::sleep(Duration::from_millis(ms));
        }

        // Parse URL to extract credentials if embedded
        let (actual_url, basic_user, basic_pass) = extract_credentials(url);

        let username = basic_user.as_deref()
            .or(self.config.username.as_deref());
        let password = basic_pass.as_deref()
            .or(self.config.password.as_deref());

        let request_builder = match self.config.verb.as_str() {
            "head" => self.client.head(&actual_url),
            "post" => self.client.post(&actual_url),
            _ => self.client.get(&actual_url),
        };

        // Add basic auth if credentials provided
        let request_builder = if let (Some(u), Some(p)) = (username, password) {
            request_builder.basic_auth(u, Some(p))
        } else if let Some(u) = username {
            request_builder.basic_auth(u, None::<&str>)
        } else {
            request_builder
        };

        // Add user agent
        let request_builder = if let Some(ref ua) = self.config.user_agent {
            request_builder.header(USER_AGENT, ua.as_str())
        } else {
            request_builder
        };

        // Add cookies
        let cookie_str = self.config.cookies.join("; ");
        let request_builder = if !cookie_str.is_empty() {
            request_builder.header(COOKIE, cookie_str.as_str())
        } else {
            request_builder
        };

        // Add custom headers
        let mut request_builder = request_builder;
        for header_str in &self.config.headers {
            if let Some(pos) = header_str.find(':') {
                let name = header_str[..pos].trim();
                let value = header_str[pos + 1..].trim();
                if let (Ok(hn), Ok(hv)) = (
                    HeaderName::from_str(name),
                    HeaderValue::from_str(value),
                ) {
                    request_builder = request_builder.header(hn, hv);
                }
            }
        }

        match request_builder.send() {
            Ok(resp) => {
                let code = resp.status().as_u16();
                let redirect_url = resp.headers()
                    .get("location")
                    .and_then(|v| v.to_str().ok())
                    .map(|s| {
                        // Resolve relative redirects
                        if s.starts_with("http://") || s.starts_with("https://") {
                            s.to_string()
                        } else {
                            // Relative redirect
                            if let Ok(base) = Url::parse(&actual_url) {
                                base.join(s).map(|u| u.to_string()).unwrap_or_else(|_| s.to_string())
                            } else {
                                s.to_string()
                            }
                        }
                    })
                    .unwrap_or_default();

                let content_len = resp.headers()
                    .get("content-length")
                    .and_then(|v| v.to_str().ok())
                    .and_then(|s| s.parse::<u64>().ok())
                    .unwrap_or(0);

                let body = if get_body && self.config.verb != "head" {
                    resp.text().ok()
                } else {
                    // For content-length from body when not in header
                    if content_len == 0 && self.config.verb != "head" {
                        let text = resp.text().ok();
                        return Some(RequestResponse {
                            url: url.to_string(),
                            code,
                            content_len: text.as_ref().map(|t| t.len() as u64).unwrap_or(0),
                            redirect_url,
                            body: text,
                        });
                    }
                    let _ = resp.bytes(); // consume body
                    None
                };

                let actual_content_len = if get_body {
                    body.as_ref().map(|b| b.len() as u64).unwrap_or(content_len)
                } else {
                    content_len
                };

                Some(RequestResponse {
                    url: url.to_string(),
                    code,
                    content_len: actual_content_len,
                    redirect_url,
                    body,
                })
            }
            Err(_e) => {
                None
            }
        }
    }
}

fn extract_credentials(url: &str) -> (String, Option<String>, Option<String>) {
    match Url::parse(url) {
        Ok(mut u) => {
            let username = if u.username().is_empty() {
                None
            } else {
                Some(u.username().to_string())
            };
            let password = u.password().map(|p| p.to_string());

            if username.is_some() {
                // Remove credentials from URL
                let _ = u.set_username("");
                let _ = u.set_password(None);
            }

            (u.to_string(), username, password)
        }
        Err(_) => (url.to_string(), None, None),
    }
}
