use markup5ever_rcdom::{Handle, NodeData, RcDom};
use url::Url;

/// Check if a response body looks like a directory listing
pub fn is_directory_listing(body: &str) -> bool {
    // Common patterns for directory listings
    let patterns = [
        "Index of /",
        "Directory listing for /",
        "<title>Directory listing",
        "Parent Directory",
        "[PARENTDIR]",
        "Directory Listing",
    ];

    for pattern in &patterns {
        if body.contains(pattern) {
            return true;
        }
    }
    false
}

/// Extract URLs from a directory listing page
pub fn scrape_urls_from_listing(body: &str, base_url: &str) -> Vec<String> {
    let dom = parse_document(RcDom::default(), Default::default())
        .from_utf8()
        .read_from(&mut body.as_bytes())
        .unwrap_or_else(|_| RcDom::default());

    let mut urls = Vec::new();
    let base = Url::parse(base_url).ok();

    extract_links(&dom.document, &base, &mut urls);

    // Filter and deduplicate
    let mut seen = std::collections::HashSet::new();
    urls.retain(|u| seen.insert(u.clone()));

    urls
}

fn extract_links(handle: &Handle, base: &Option<Url>, urls: &mut Vec<String>) {
    let node = handle;

    if let NodeData::Element { ref name, ref attrs, .. } = node.data {
        let tag_name = name.local.as_ref();
        let attrs = attrs.borrow();

        if tag_name == "a" {
            for attr in attrs.iter() {
                if attr.name.local.as_ref() == "href" {
                    let href = attr.value.as_ref();
                    // Skip parent dir links and anchors
                    if href == "/" || href == "../" || href.starts_with('#') || href.starts_with('?') {
                        continue;
                    }
                    // Skip absolute URLs that are external
                    if href.starts_with("http://") || href.starts_with("https://") {
                        urls.push(href.to_string());
                    } else if !href.is_empty() {
                        // Relative URL
                        if let Some(ref base_url) = base {
                            if let Ok(resolved) = base_url.join(href) {
                                urls.push(resolved.to_string());
                            }
                        }
                    }
                }
            }
        }
    }

    for child in node.children.borrow().iter() {
        extract_links(child, base, urls);
    }
}
