use serde::Serialize;
use std::io::Write;
use std::fs::File;

use crate::arg_parse::GlobalOpts;

#[derive(Debug, Clone, Serialize)]
pub struct ScanResult {
    pub url: String,
    pub code: u16,
    pub size: u64,
    pub is_directory: bool,
    pub is_listable: bool,
    pub redirect_url: String,
    pub found_from_listable: bool,
}

impl ScanResult {
    pub fn new(url: String, code: u16, size: u64, is_directory: bool, is_listable: bool,
               redirect_url: String, found_from_listable: bool) -> Self {
        ScanResult { url, code, size, is_directory, is_listable, redirect_url, found_from_listable }
    }

    pub fn format_line(&self, no_color: bool, indent: &str) -> String {
        let prefix = if self.is_listable {
            format!("{}L ", indent)
        } else if self.is_directory {
            format!("{}D ", indent)
        } else {
            format!("{}+ ", indent)
        };

        let code_str = if no_color {
            format!("{}", self.code)
        } else {
            color_code(self.code)
        };

        let dest_part = if !self.redirect_url.is_empty() {
            format!("|DEST:{}", self.redirect_url)
        } else {
            String::new()
        };

        format!("{}{}(CODE:{}|SIZE:{}{})", prefix, self.url, code_str, self.size, dest_part)
    }
}

pub fn color_code(code: u16) -> String {
    let color = match code {
        200..=299 => "\x1b[32m",  // green
        300..=399 => "\x1b[36m",  // cyan
        400..=499 => "\x1b[31m",  // red
        500..=599 => "\x1b[33m",  // yellow
        _ => "",
    };
    if color.is_empty() {
        format!("{}", code)
    } else {
        format!("{}{}\x1b[0m", color, code)
    }
}

pub struct OutputConfig {
    pub output_file: Option<File>,
    pub json_file: Option<String>,
    pub xml_file: Option<String>,
    pub no_color: bool,
    pub silent: bool,
    pub is_tty: bool,
    pub hide_lengths: Vec<(u64, u64)>,
    pub code_blacklist: Vec<u16>,
    pub code_whitelist: Vec<u16>,
}

pub fn should_hide(result: &ScanResult, hide_lengths: &[(u64, u64)], 
                   code_blacklist: &[u16], code_whitelist: &[u16]) -> bool {
    // Check whitelist first
    if !code_whitelist.is_empty() {
        if !code_whitelist.contains(&result.code) {
            return true;
        }
    }

    // Check blacklist
    if code_blacklist.contains(&result.code) {
        return true;
    }

    // Check length blacklist (only for files, not directories in live output)
    if !result.is_directory && !result.is_listable {
        for &(lo, hi) in hide_lengths {
            if result.size >= lo && result.size <= hi {
                return true;
            }
        }
    }

    false
}

/// Generate the text report
pub fn generate_report(results: &[ScanResult], base_url: &str, no_color: bool, is_tty: bool) -> String {
    let mut output = String::new();
    let indent = if is_tty { "  " } else { "" };

    output.push_str(&format!("Dirble Scan Report for {}:\n", base_url));

    // Collect all results at this level (non-recursive items + top-level dirs)
    let (files, dirs): (Vec<&ScanResult>, Vec<&ScanResult>) = results.iter()
        .partition(|r| !r.is_directory && !r.is_listable);

    // Print files first
    for file in &files {
        if !is_tty {
            output.push_str(&format!("{}\n", file.format_line(no_color, "")));
        } else {
            let line = file.format_line(no_color, indent);
            output.push_str(&format!("{}\n", line));
        }
    }

    if !files.is_empty() {
        // Don't add newline after files if there are dirs following
    }

    // Print directories with their contents
    for dir in &dirs {
        output.push('\n');
        if !is_tty {
            output.push_str(&format!("{}\n", format_result_line(dir, no_color, "")));
        } else {
            output.push_str(&format!("{}\n", format_result_line(dir, no_color, indent)));
        }
        // TODO: Print files under directory
        output.push('\n');
    }

    output
}

fn format_result_line(result: &ScanResult, no_color: bool, indent: &str) -> String {
    result.format_line(no_color, indent)
}

pub fn write_json(results: &[ScanResult], filename: &str) {
    let mut file = match File::create(filename) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("[ERROR] Failed to create JSON file '{}': {}", filename, e);
            return;
        }
    };

    // Write each result as a JSON object, one per line
    // Format: [obj1,\nobj2,\n...,\nobjN]
    let json_str = serde_json::to_string_pretty(results).unwrap_or_default();
    let _ = file.write_all(json_str.as_bytes());
}

pub fn write_xml(results: &[ScanResult], filename: &str) {
    let mut file = match File::create(filename) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("[ERROR] Failed to create XML file '{}': {}", filename, e);
            return;
        }
    };

    let mut xml = String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<dirble_scan>\n");

    for result in results {
        xml.push_str(&format!(
            "<path url=\"{}\" code=\"{}\" content_len=\"{}\" is_directory=\"{}\" is_listable=\"{}\" redirect_url=\"{}\" found_from_listable=\"{}\"/>\n",
            result.url, result.code, result.size,
            result.is_directory, result.is_listable,
            result.redirect_url, result.found_from_listable
        ));
    }

    xml.push_str("</dirble_scan>");

    let _ = file.write_all(xml.as_bytes());
}
