fn print_header(args: &GlobalOpts, uris: &[String], wordlist_path: &str, 
                prefixes: &[String], extensions: &[String]) {
    println!("Dirble 1.4.2 (commit d520c82, build 2026-04-17)");
    println!("Developed by Izzy Whistlecroft");

    // Targets
    for uri in uris {
        let target = if uri.ends_with('/') {
            uri.clone()
        } else {
            // Get the directory part
            get_base_scan_url(uri)
        };
        println!("Targets: {}", target);
    }

    // Wordlist
    println!("Wordlists: {}", wordlist_path);

    // Prefixes
    if prefixes.is_empty() {
        println!("No Prefixes");
    } else {
        println!("Prefixes: {}", prefixes.join(" "));
    }

    // Extensions
    if extensions.is_empty() {
        println!("No Extensions");
    } else {
        println!("Extensions: {}", extensions.join(" "));
    }

    // Hidden lengths
    let hide_lengths = args.get_hide_lengths();
    if hide_lengths.is_empty() {
        println!("No lengths hidden");
    } else {
        let ranges: Vec<String> = hide_lengths.iter().map(|(lo, hi)| {
            if lo == hi {
                format!("{}", lo)
            } else {
                format!("{}-{}", lo, hi)
            }
        }).collect();
        println!("Hidden lengths: [{}]", ranges.join(", "));
    }

    println!();
}

fn get_base_scan_url(uri: &str) -> String {
    use url::Url;
    if uri.ends_with('/') {
        return uri.to_string();
    }
    match Url::parse(uri) {
        Ok(mut u) => {
            let path = u.path().to_string();
            if path == "/" || path.is_empty() {
                if let Ok(mut u2) = Url::parse(uri) {
                    u2.set_path("/");
                    u2.to_string()
                } else {
                    format!("{}/", uri)
                }
            } else {
                // Strip last path component
                let parent = if let Some(pos) = path.rfind('/') {
                    path[..pos + 1].to_string()
                } else {
                    "/".to_string()
                };
                u.set_path(&parent);
                u.to_string()
            }
        }
        Err(_) => format!("{}/", uri),
    }
}
