use crate::output_thread::OutputMessage;
use crate::request::{RequestClient, RequestConfig, RequestResponse};

const RANDOM_CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";

/// Generates a random alphanumeric string of the given length
fn random_string(len: usize) -> String {
    let mut rng = rand::thread_rng();
    (0..len)
        .map(|_| RANDOM_CHARS[rng.gen_range(0..RANDOM_CHARS.len())] as char)
        .collect()
}

/// The "not found" indicator for a URL
#[derive(Debug, Clone)]
pub struct NotFoundDetection {
    pub code: u16,
    pub redirect_dest: Option<String>,
}

/// Detect the "not found" code for a given base URL
pub fn detect_not_found(client: &RequestClient, base_url: &str) -> NotFoundDetection {
    let probe_lens = [10, 20, 30];
    let mut codes = Vec::new();
    let mut dests = Vec::new();

    for &len in &probe_lens {
        let random_path = random_string(len);
        let probe_url = format!("{}{}", base_url, random_path);

        if let Some(resp) = client.request(&probe_url, false) {
            codes.push(resp.code);
            dests.push(resp.redirect_url.clone());
        } else {
            codes.push(0);
            dests.push(String::new());
        }
    }

    // Find the most common code
    let code = if codes.is_empty() {
        404
    } else {
        // Check if all codes agree
        let first = codes[0];
        if codes.iter().all(|&c| c == first) {
            first
        } else {
            // Use the most common code, or 404 as default
            let mut counts = std::collections::HashMap::new();
            for &c in &codes {
                *counts.entry(c).or_insert(0usize) += 1;
            }
            *counts.iter().max_by_key(|(_, &v)| v).map(|(k, _)| k).unwrap_or(&404)
        }
    };

    // For redirects, check if destination is consistent
    let redirect_dest = if code >= 300 && code < 400 {
        // Use the most common destination
        let first_dest = dests.iter().find(|d| !d.is_empty()).cloned();
        if dests.iter().filter(|d| !d.is_empty()).all(|d| Some(d.as_str()) == first_dest.as_deref()) {
            first_dest
        } else {
            None
        }
    } else {
        None
    };

    NotFoundDetection { code, redirect_dest }
}

/// Check if a response matches the "not found" condition
pub fn matches_not_found(resp: &RequestResponse, detection: &NotFoundDetection) -> bool {
    if resp.code != detection.code {
        return false;
    }

    // For redirects, check destination too
    if let Some(ref expected_dest) = detection.redirect_dest {
        if resp.redirect_url != *expected_dest {
            return false;
        }
    }

    true
}

/// Represents a scan job for a directory
#[derive(Debug, Clone)]
pub struct ScanJob {
    pub url: String,
    pub depth: u32,
    pub found_from_listable: bool,
}

/// Run the scanner for all URIs
pub fn scan_all_uris(
    uris: &[String],
    wordlist: &[String],
    extensions: &[String],
    prefixes: &[String],
    args: &GlobalOpts,
    config: Arc<RequestConfig>,
    output_tx: Sender<OutputMessage>,
) {
    let client = RequestClient::new((*config).clone());

    // Collect all initial scan jobs
    let mut initial_jobs: Vec<ScanJob> = Vec::new();

    for uri in uris {
        // Normalize the URL
        let base_url = normalize_to_dir(uri);
        let display_url = uri.clone();

        // Detect not-found for this URL
        let detection = if !args.disable_validator && args.code_whitelist.is_empty() {
            // Probe from the base URL (parent dir if no trailing slash)
            let probe_base = if uri.ends_with('/') {
                uri.clone()
            } else {
                base_url.clone()
            };
            let det = detect_not_found(&client, &probe_base);

            // Print detection info
            let det_str = if let Some(ref dest) = det.redirect_dest {
                format!("[INFO] Detected nonexistent paths for {} are (CODE:{}|DEST:{})",
                    display_url, det.code, dest)
            } else {
                format!("[INFO] Detected nonexistent paths for {} are (CODE:{})",
                    display_url, det.code)
            };
            println!("{}", det_str);

            Some(det)
        } else {
            None
        };

        // Send detection info to output thread
        output_tx.send(OutputMessage::Detection {
            url: display_url.clone(),
            base_url: base_url.clone(),
            detection: detection.clone(),
        }).ok();

        initial_jobs.push(ScanJob {
            url: base_url.clone(),
            depth: 0,
            found_from_listable: false,
        });
    }

    // Now scan each initial job
    // For initial scans, we may increase the wordlist split
    let available_threads = if args.max_threads > 2 { args.max_threads - 2 } else { 1 };
    let initial_split = if available_threads > args.wordlist_split {
        available_threads
    } else {
        args.wordlist_split
    };

    // Build ext combos: (no-ext or ext) and optionally prefix
    let ext_combos = build_ext_combos(extensions, args.force_extension);

    // For each initial URI, scan with increased split
    let mut all_detections: Vec<(String, Option<NotFoundDetection>)> = Vec::new();

    // Re-collect detections for job processing
    for (i, uri) in uris.iter().enumerate() {
        let base_url = normalize_to_dir(uri);
        // We need to re-detect since we already sent them
        all_detections.push((base_url, None)); // Will be filled in by output thread
    }

    // Actually, let's simplify - just scan synchronously with threads
    scan_directory_recursive(
        &initial_jobs[..],
        wordlist,
        &ext_combos,
        prefixes,
        args,
        &config,
        &output_tx,
        initial_split,
        true, // is_initial
    );

    // Signal end of all scanning
    output_tx.send(OutputMessage::Done).ok();
}

/// Build the list of extension combinations to use
/// Returns Vec<Option<String>> where None means "no extension"
fn build_ext_combos(extensions: &[String], force_extension: bool) -> Vec<Option<String>> {
    let mut combos = Vec::new();

    if !force_extension {
        // Always include "no extension" unless force_extension
        combos.push(None);
    }

    for ext in extensions {
        combos.push(Some(ext.clone()));
    }

    combos
}

