#[allow(clippy::too_many_arguments)]
fn process_response(
    url: &str,
    resp: RequestResponse,
    detection: &Option<NotFoundDetection>,
    tx: &Sender<OutputMessage>,
    discovered: &Arc<Mutex<Vec<SubDirInfo>>>,
    show_htaccess: bool,
    code_blacklist: Vec<u16>,
    code_whitelist: Vec<u16>,
    hide_lengths: Vec<(u64, u64)>,
    disable_validator: bool,
    _silent: bool,
    scan_listable: bool,
    scrape_listable: bool,
    disable_recursion: bool,
    max_recursion_depth: Option<u32>,
    current_depth: u32,
    found_from_listable: bool,
    scan_401: bool,
    scan_403: bool,
    is_dir_check: bool,
) {
    // Check if this matches "not found"
    if let Some(ref det) = detection {
        if det.matches(&resp) {
            log::trace!("[src/request_thread.rs:179] [{}]: matches Not Found condition", url);
            return;
        }
    }

    // Determine if it's a directory/listable
    let (is_directory, is_listable) = if is_dir_check {
        let listing = if let Some(ref body) = resp.body {
            content_parse::is_directory_listing(body)
        } else {
            false
        };
        (true, listing)
    } else {
        (false, false)
    };

    // Skip 404 responses unless whitelisted
    if resp.code == 404 && code_whitelist.is_empty() && detection.is_none() {
        return;
    }

    // Check if response code is filtered
    if !code_whitelist.is_empty() && !code_whitelist.contains(&resp.code) {
        return;
    }
    if code_blacklist.contains(&resp.code) {
        return;
    }

