            if let Some(ref body) = resp.body {
                let scraped_urls = content_parse::scrape_urls_from_listing(body, url);
                for scraped_url in scraped_urls {
                    // Send each scraped URL as a result
                    if let Some(scraped_resp) = {
                        let client = RequestClient::new(RequestConfig {
                            timeout: std::time::Duration::from_secs(5),
                            max_errors: 5,
                            verb: "get".to_string(),
                            user_agent: None,
                            cookies: vec![],
                            headers: vec![],
                            proxy: None,
                            no_proxy: false,
                            ignore_cert: false,
                            throttle: None,
                            username: None,
                            password: None,
                        });
                        // Don't actually request here - just log the found URL
                        log::trace!("[src/request_thread.rs:174] [{}]: code 0 detected", scraped_url);
                        None::<RequestResponse>
                    } {
                        // Process scraped response
                    }

                    // For listable scraping, we add the URL as a discovered directory
                    if scraped_url.ends_with('/') {
                        let mut disc = discovered.lock().unwrap();
                        disc.push(SubDirInfo {
                            url: scraped_url,
                            depth: current_depth + 1,
                            found_from_listable: true,
                            is_listable: false,
                        });
                    }
                }
            }
        }
    }
}

/// Process subdirectories recursively
pub fn process_subdirs(
    subdirs: Vec<SubDirInfo>,
    wordlist: &[String],
    ext_combos: &[Option<String>],
    prefixes: &[String],
    args: &GlobalOpts,
    config: Arc<RequestConfig>,
    output_tx: &Sender<OutputMessage>,
    depth: u32,
) {
    for subdir in subdirs {
        // Check max recursion depth
        if let Some(max_depth) = args.max_recursion_depth {
            if depth > max_depth {
                continue;
            }
        }

        if args.disable_recursion {
            continue;
        }

        // Detect not-found for this directory
        let client = RequestClient::new((*config).clone());

        let detection = if !args.disable_validator && args.code_whitelist.is_empty() {
            let det = detect_not_found(&client, &subdir.url);
            let msg = if let Some(ref dest) = det.redirect_dest {
                format!("[INFO] Detected nonexistent paths for {} are (CODE:{}|DEST:{})",
                    subdir.url, det.code, dest)
            } else {
                format!("[INFO] Detected nonexistent paths for {} are (CODE:{})",
                    subdir.url, det.code)
            };
            println!("{}", msg);
            Some(det)
        } else {
            None
        };

        let new_subdirs = scan_directory(
            &subdir.url,
            wordlist,
            ext_combos,
            prefixes,
            args,
            Arc::clone(&config),
            output_tx,
            detection.as_ref(),
            args.wordlist_split,
            depth,
            subdir.found_from_listable,
        );

        process_subdirs(
            new_subdirs,
            wordlist,
            ext_combos,
            prefixes,
            args,
            Arc::clone(&config),
            output_tx,
            depth + 1,
        );
    }
}

/// Split wordlist into n chunks (each chunk gets roughly equal size)
fn split_wordlist(wordlist: &[String], n: usize) -> Vec<Vec<String>> {
    let n = n.max(1);
    let total = wordlist.len();

    // Always create n chunks, even if some are empty
    let mut chunks: Vec<Vec<String>> = vec![vec![]; n];

    for (i, word) in wordlist.iter().enumerate() {
        chunks[i % n].push(word.clone());
    }

    chunks
}
