/// Normalize URI to directory URL
pub fn normalize_to_dir(uri: &str) -> String {
    if uri.ends_with('/') {
        return uri.to_string();
    }

    match Url::parse(uri) {
        Ok(mut u) => {
            let path = u.path().to_string();
            if path == "/" || path.is_empty() {
                u.set_path("/");
                u.to_string()
            } else {
                let parent = if let Some(pos) = path.rfind('/') {
                    let p = &path[..pos + 1];
                    if p.is_empty() { "/" } else { p }
                } else {
                    "/"
                };
                u.set_path(parent);
                u.to_string()
            }
        }
        Err(_) => format!("{}/", uri),
    }
}

