pub fn detect_not_found(client: &RequestClient, base_url: &str) -> NotFoundDetection {
    let mut codes = Vec::new();
    let mut dests = Vec::new();

    for &len in &PROBE_LENGTHS {
        let random_path = random_string(len);
        let probe_url = format!("{}{}", base_url, random_path);

        if let Some(resp) = client.request(&probe_url, false) {
