/// Normalize URI to directory URL
pub fn normalize_to_dir(uri: &str) -> String {
    if uri.ends_with('/') {
        return uri.to_string();
    }

    match Url::parse(uri) {
        Ok(mut u) => {
            let path = u.path().to_string();
            if path == "/" || path.is_empty() {
                u.set_path("/");
                u.to_string()
            } else {
                let parent = if let Some(pos) = path.rfind('/') {
                    let p = &path[..pos + 1];
                    if p.is_empty() { "/" } else { p }
                } else {
                    "/"
                };
                u.set_path(parent);
                u.to_string()
            }
        }
        Err(_) => format!("{}/", uri),
    }
}

/// Get URL depth (number of non-empty path segments)
pub fn url_depth(url: &str) -> u32 {
    match Url::parse(url) {
        Ok(u) => {
            u.path().trim_matches('/').split('/').filter(|s| !s.is_empty()).count() as u32
        }
        Err(_) => 0,
    }
}

