use std::fs;
use crossbeam_channel::Receiver;

use crate::arg_parse::GlobalOpts;
use crate::output::ScanResult;

#[derive(Debug)]
pub enum OutputMessage {
    StartUrl {
        display_url: String,
        base_url: String,
    },
    Detection {
        url: String,
        base_url: String,
        detection: Option<crate::request_thread::NotFoundDetection>,
    },
    Result {
        url: String,
        code: u16,
        size: u64,
        is_directory: bool,
        is_listable: bool,
        redirect_url: String,
        found_from_listable: bool,
    },
    Done,
}

pub struct OutputThread {
    rx: Receiver<OutputMessage>,
    args: Arc<GlobalOpts>,
    uris: Vec<String>,
    hide_lengths: Vec<(u64, u64)>,
    code_blacklist: Vec<u16>,
    code_whitelist: Vec<u16>,
    json_file: Option<String>,
    xml_file: Option<String>,
    txt_file: Option<String>,
    results: Vec<ScanResult>,
    url_to_base: HashMap<String, String>,
    is_tty: bool,
}

impl OutputThread {
    pub fn new(
        rx: Receiver<OutputMessage>,
        args: Arc<GlobalOpts>,
        uris: Vec<String>,
        hide_lengths: Vec<(u64, u64)>,
        code_blacklist: Vec<u16>,
        code_whitelist: Vec<u16>,
        json_file: Option<String>,
        xml_file: Option<String>,
        txt_file: Option<String>,
    ) -> Self {
        let is_tty = atty::is(atty::Stream::Stdout);
        OutputThread {
            rx, args, uris, hide_lengths, code_blacklist, code_whitelist,
            json_file, xml_file, txt_file,
            results: Vec::new(),
            url_to_base: HashMap::new(),
            is_tty,
        }
    }

    pub fn run(&mut self) {
        log::debug!("Output thread starting");

        loop {
            match self.rx.recv() {
                Ok(msg) => {
                    match msg {
                        OutputMessage::Done => break,
                        OutputMessage::StartUrl { display_url, base_url } => {
                            self.url_to_base.insert(display_url, base_url);
                        }
                        OutputMessage::Detection { .. } => {
                            // Detection info already printed by scanner
                        }
                        OutputMessage::Result { url, code, size, is_directory, is_listable, 
                                                redirect_url, found_from_listable } => {
                            let result = ScanResult {
                                url: url.clone(),
                                code,
                                size,
                                is_directory,
                                is_listable,
                                redirect_url: redirect_url.clone(),
                                found_from_listable,
                            };

                            // Check if should be shown
                            if !self.should_hide(&result) {
                                // Print live output
                                if !self.args.silent {
                                    self.print_result(&result, false);
                                }
                            }

                            self.results.push(result);
                        }
                    }
                }
                Err(_) => break,
            }
        }

        log::debug!("Received signal to end, generating the report");

        // Generate reports
        self.generate_reports();
    }

    fn should_hide(&self, result: &ScanResult) -> bool {
        // Whitelist check
        if !self.code_whitelist.is_empty() && !self.code_whitelist.contains(&result.code) {
            return true;
        }

        // Blacklist check
        if self.code_blacklist.contains(&result.code) {
            return true;
        }

        // Hide-lengths check (only for files)
        if !result.is_directory && !result.is_listable {
            for &(lo, hi) in &self.hide_lengths {
                if result.size >= lo && result.size <= hi {
                    return true;
                }
            }
        }

        false
    }

    fn print_result(&self, result: &ScanResult, indent_report: bool) {
        let indent = if indent_report && self.is_tty { "  " } else { "" };
        let nested_indent = if indent_report && self.is_tty { "    " } else { "" };

        let line = self.format_result_line(result, indent);
        println!("{}", line);
    }

    fn format_result_line(&self, result: &ScanResult, indent: &str) -> String {
        let no_color = self.args.no_color;

        let prefix = if result.is_listable {
            if !no_color && self.is_tty {
                format!("{}\x1b[1mL \x1b[0m", indent)
            } else {
                format!("{}L ", indent)
            }
        } else if result.is_directory {
            format!("{}D ", indent)
        } else {
            format!("{}+ ", indent)
        };

        let code_str = if no_color || !self.is_tty {
            format!("{}", result.code)
        } else {
            crate::output::color_code(result.code)
        };

        let dest_part = if !result.redirect_url.is_empty() {
            format!("|DEST:{}", result.redirect_url)
        } else {
            String::new()
        };

        format!("{}{}(CODE:{}|SIZE:{}{})", prefix, result.url, code_str, result.size, dest_part)
    }

    fn generate_reports(&self) {
        // Generate text report
        let report = self.generate_text_report();

        // Write to txt file if specified
        if let Some(ref txt_file) = self.txt_file {
            if let Ok(mut f) = fs::File::create(txt_file) {
                let _ = f.write_all(report.as_bytes());
            }
        }

        // Print to stdout if tty
        if self.is_tty {
            print!("\n{}", report);
        } else {
            // If not tty and not silent, just don't print report to stdout
            // (it goes to file only)
        }

        // Generate JSON
        if let Some(ref json_file) = self.json_file {
            self.write_json(json_file);
        }

        // Generate XML
        if let Some(ref xml_file) = self.xml_file {
            self.write_xml(xml_file);
        }
    }

    fn generate_text_report(&self) -> String {
        let mut output = String::new();

        // Generate one report section per URI
        for uri in &self.uris {
            let base_url = crate::request_thread::normalize_to_dir(uri);

            output.push_str(&format!("Dirble Scan Report for {}:\n", base_url));

            // Get all results for this base URL
            let base_results: Vec<&ScanResult> = self.results.iter()
                .filter(|r| self.should_hide(r) == false)
                .filter(|r| r.url.starts_with(&base_url))
                .collect();

            // Build a tree structure
            output.push_str(&self.format_tree(&base_url, &base_results));
        }

        output
    }

    fn format_tree(&self, base_url: &str, results: &[&ScanResult]) -> String {
        let mut output = String::new();
        let indent = if self.is_tty { "  " } else { "" };
        let nested_indent = if self.is_tty { "    " } else { "" };

        // Get direct children of base_url
        let (files, dirs): (Vec<&&ScanResult>, Vec<&&ScanResult>) = results.iter()
            .filter(|r| is_direct_child(&r.url, base_url))
            .partition(|r| !r.is_directory && !r.is_listable);

        // Print files first
        for file in &files {
            output.push_str(&format!("{}\n", self.format_result_line(file, indent)));
        }

        // Print directories with their contents
        for dir in &dirs {
            output.push('\n');
            output.push_str(&format!("{}\n", self.format_result_line(dir, indent)));

            // Print direct children of this directory (files only)
            let dir_children: Vec<&ScanResult> = results.iter()
                .map(|r| *r)
                .filter(|r| is_direct_child(&r.url, &dir.url))
                .filter(|r| !r.is_directory && !r.is_listable)
                .collect();

            for child in &dir_children {
                output.push_str(&format!("{}\n", self.format_result_line(child, nested_indent)));
            }

            // Print sub-directories of this directory
            let sub_dirs: Vec<&ScanResult> = results.iter()
                .map(|r| *r)
                .filter(|r| is_direct_child(&r.url, &dir.url))
                .filter(|r| r.is_directory || r.is_listable)
                .collect();

            for sub_dir in &sub_dirs {
                output.push('\n');
                // This is level 2, indent more
                let inner_indent = if self.is_tty { "    " } else { "" };
                output.push_str(&format!("{}\n", self.format_result_line(sub_dir, inner_indent)));

                // Files under sub_dir (level 3)
                let sub_children: Vec<&ScanResult> = results.iter()
                    .map(|r| *r)
                    .filter(|r| is_direct_child(&r.url, &sub_dir.url))
                    .filter(|r| !r.is_directory && !r.is_listable)
                    .collect();

                let deep_indent = if self.is_tty { "      " } else { "" };
                for child in &sub_children {
                    output.push_str(&format!("{}\n", self.format_result_line(child, deep_indent)));
                }
            }

            output.push('\n');
        }

        // Handle top-level listable dirs separately
        // (they don't show files inside them)

        output
    }

    fn write_json(&self, filename: &str) {
        let results: Vec<&ScanResult> = self.results.iter().collect();

        if results.is_empty() {
            if let Ok(mut f) = fs::File::create(filename) {
                let _ = f.write_all(b"[]");
            }
            return;
        }

        match fs::File::create(filename) {
            Ok(mut f) => {
                let last_idx = results.len() - 1;
                let _ = write!(f, "[");
                for (i, r) in results.iter().enumerate() {
                    let json = serde_json::json!({
                        "url": r.url,
                        "code": r.code,
                        "size": r.size,
                        "is_directory": r.is_directory,
                        "is_listable": r.is_listable,
                        "redirect_url": r.redirect_url,
                        "found_from_listable": r.found_from_listable,
                    });
                    let json_str = serde_json::to_string(&json).unwrap_or_default();
                    if i < last_idx {
                        let _ = writeln!(f, "{},", json_str);
                    } else {
                        let _ = write!(f, "{}]", json_str);
                    }
                }
            }
            Err(e) => {
                eprintln!("[ERROR] Failed to write JSON file '{}': {}", filename, e);
            }
        }
    }

    fn write_xml(&self, filename: &str) {
        match fs::File::create(filename) {
            Ok(mut f) => {
                let _ = write!(f, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<dirble_scan>\n");
                for r in &self.results {
                    let _ = write!(f, 
                        "<path url=\"{}\" code=\"{}\" content_len=\"{}\" is_directory=\"{}\" is_listable=\"{}\" redirect_url=\"{}\" found_from_listable=\"{}\"/>\n",
                        r.url, r.code, r.size, r.is_directory, r.is_listable, r.redirect_url, r.found_from_listable
                    );
                }
                let _ = write!(f, "</dirble_scan>");
            }
            Err(e) => {
                eprintln!("[ERROR] Failed to write XML file '{}': {}", filename, e);
            }
        }
    }
}

fn is_direct_child(url: &str, parent: &str) -> bool {
    if !url.starts_with(parent) {
        return false;
    }

    let rest = &url[parent.len()..];

    // For directories (ending with /), the rest should be "name/"
    // For files, the rest should be "name.ext"

    if url.ends_with('/') {
        // It's a directory
        let name_part = rest.trim_end_matches('/');
        !name_part.contains('/')
    } else {
        // It's a file
        !rest.contains('/')
    }
}
