        let is_tty = atty::is(atty::Stream::Stdout);
        OutputThread {
            rx, args, uris, hide_lengths, code_blacklist, code_whitelist,
            json_file, xml_file, txt_file,
            results: Vec::new(),
            url_to_base: HashMap::new(),
            is_tty,
        }
    }

    pub fn run(&mut self) {
        log::debug!("Output thread starting");

        loop {
            match self.rx.recv() {
                Ok(msg) => {
                    match msg {
                        OutputMessage::Done => break,
                        OutputMessage::StartUrl { display_url, base_url } => {
                            self.url_to_base.insert(display_url, base_url);
                        }
                        OutputMessage::Detection { .. } => {
                            // Detection info already printed by scanner
                        }
                        OutputMessage::Result { url, code, size, is_directory, is_listable, 
                                                redirect_url, found_from_listable } => {
                            let result = ScanResult {
                                url: url.clone(),
                                code,
                                size,
                                is_directory,
                                is_listable,
                                redirect_url: redirect_url.clone(),
                                found_from_listable,
                            };

                            // Check if should be shown
                            if !self.should_hide(&result) {
                                // Print live output
                                if !self.args.silent {
                                    self.print_result(&result, false);
                                }
                            }

                            self.results.push(result);
                        }
                    }
                }
                Err(_) => break,
            }
        }

        log::debug!("Received signal to end, generating the report");

        // Generate reports
        self.generate_reports();
    }

    fn should_hide(&self, result: &ScanResult) -> bool {
        // Whitelist check
        if !self.code_whitelist.is_empty() && !self.code_whitelist.contains(&result.code) {
            return true;
        }

        // Blacklist check
        if self.code_blacklist.contains(&result.code) {
            return true;
        }

        // Hide-lengths check (only for files)
        if !result.is_directory && !result.is_listable {
            for &(lo, hi) in &self.hide_lengths {
                if result.size >= lo && result.size <= hi {
                    return true;
                }
            }
        }

        false
    }

    fn print_result(&self, result: &ScanResult, indent_report: bool) {
        let indent = if indent_report && self.is_tty { "  " } else { "" };
        let nested_indent = if indent_report && self.is_tty { "    " } else { "" };

        let line = self.format_result_line(result, indent);
        println!("{}", line);
    }

    fn format_result_line(&self, result: &ScanResult, indent: &str) -> String {
        let no_color = self.args.no_color;

        let prefix = if result.is_listable {
            if !no_color && self.is_tty {
                format!("{}\x1b[1mL \x1b[0m", indent)
            } else {
