    if 200 <= code <= 299:
        return f"{COLOR_GREEN}{code}{COLOR_RESET}"
    elif 300 <= code <= 399:
        return f"{COLOR_CYAN}{code}{COLOR_RESET}"
    elif 400 <= code <= 499:
