            clean_url = urllib.parse.urlunparse((parsed.scheme, netloc, parsed.path,
                                                 parsed.params, parsed.query, parsed.fragment))
        else:
            clean_url = url

        # Build request
        req = urllib.request.Request(clean_url, method=self.verb)

        # Add auth
        if username:
            import base64
            creds = base64.b64encode(f"{username}:{password or ''}".encode()).decode()
            req.add_header('Authorization', f'Basic {creds}')

        # Add user agent
        if self.user_agent:
            req.add_header('User-Agent', self.user_agent)

        # Add cookies
        if self.cookies:
            cookie_str = '; '.join(self.cookies)
            req.add_header('Cookie', cookie_str)

