        for header in self.headers:
            if ':' in header:
                name, _, value = header.partition(':')
                req.add_header(name.strip(), value.strip())

        # SSL context
        ssl_ctx = ssl.create_default_context()
        if self.ignore_cert:
            ssl_ctx.check_hostname = False
            ssl_ctx.verify_mode = ssl.CERT_NONE

        # Proxy
        if self.proxy and not self.no_proxy:
            proxy_handler = urllib.request.ProxyHandler({'http': self.proxy, 'https': self.proxy})
            opener = urllib.request.build_opener(proxy_handler)
        else:
            opener = urllib.request.build_opener(urllib.request.HTTPSHandler(context=ssl_ctx))

        try:
            # Don't follow redirects
            class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
                def redirect_request(self, req, fp, code, msg, headers, newurl):
                    return None

            opener.add_handler(NoRedirectHandler())

            with opener.open(req, timeout=self.timeout) as resp:
                code = resp.status
                content_len = resp.headers.get('Content-Length')
                redirect_url = ""

                if content_len:
                    try:
                        content_len = int(content_len)
                    except ValueError:
                        content_len = 0
                else:
                    content_len = None

                body = None
                if get_body and self.verb != 'HEAD':
                    body = resp.read().decode('utf-8', errors='replace')
                    if content_len is None:
                        content_len = len(body)
                else:
                    resp.read()  # consume
                    if content_len is None:
                        content_len = 0

                return {
                    'code': code,
                    'size': content_len or 0,
                    'redirect_url': redirect_url,
                    'body': body,
                }
        except urllib.error.HTTPError as e:
            code = e.code
            content_len = e.headers.get('Content-Length')
            redirect_url = ""

            if 300 <= code <= 399:
                redirect_url = e.headers.get('Location', '')
                if redirect_url and not redirect_url.startswith(('http://', 'https://')):
                    try:
                        redirect_url = urllib.parse.urljoin(url, redirect_url)
                    except Exception:
                        pass

            if content_len:
                try:
                    content_len = int(content_len)
                except ValueError:
                    content_len = 0
            else:
                content_len = 0

            body = None
            if get_body and self.verb != 'HEAD':
                try:
                    body_bytes = e.read()
                    body = body_bytes.decode('utf-8', errors='replace')
                    if not content_len:
                        content_len = len(body)
                except Exception:
                    pass

            return {
                'code': code,
                'size': content_len,
                'redirect_url': redirect_url,
                'body': body,
            }
        except (urllib.error.URLError, socket.timeout, ConnectionResetError, OSError) as e:
            return None
        except Exception as e:
            return None

# Global verbose level
VERBOSE_LEVEL = 0

class NotFoundDetection:
    def __init__(self, code: int, redirect_dest: str = ""):
        self.code = code
        self.redirect_dest = redirect_dest

    def matches(self, resp: Dict) -> bool:
        if resp['code'] != self.code:
            return False
        if self.redirect_dest:
            if resp.get('redirect_url', '') != self.redirect_dest:
                return False
        return True

def detect_not_found(client: HTTPClient, base_url: str) -> NotFoundDetection:
    """Probe for the 'not found' code at base_url"""
    probe_lengths = [10, 20, 30]
    codes = []
    dests = []

    for length in probe_lengths:
        probe_path = random_string(length)
        probe_url = base_url + probe_path

        resp = client.request(probe_url, False)
        if resp:
            codes.append(resp['code'])
            dests.append(resp.get('redirect_url', ''))
        else:
            codes.append(0)
            dests.append('')

    if not codes:
        return NotFoundDetection(404)

    # Find majority code
    first = codes[0]
    if all(c == first for c in codes):
        code = first
    else:
        from collections import Counter
        count = Counter(codes)
        code = count.most_common(1)[0][0]

    # For redirects, check consistent destination
    redirect_dest = ""
    if 300 <= code <= 399:
        non_empty = [d for d in dests if d]
        if non_empty and all(d == non_empty[0] for d in non_empty):
            redirect_dest = non_empty[0]

    return NotFoundDetection(code, redirect_dest)

class OutputManager:
    def __init__(self, args, uris: List[str]):
        self.args = args
        self.uris = uris
        self.results = []
        self.lock = threading.Lock()
        self.is_tty = is_tty()

        self.hide_lengths = parse_hide_lengths(getattr(args, 'hide_lengths', []))
        self.code_blacklist = parse_codes(getattr(args, 'code_blacklist', []))
        self.code_whitelist = parse_codes(getattr(args, 'code_whitelist', []))
        self.no_color = getattr(args, 'no_color', False)
        self.silent = getattr(args, 'silent', False)

    def should_hide(self, result: ScanResult) -> bool:
        # Whitelist check
        if self.code_whitelist and result.code not in self.code_whitelist:
            return True
        # Blacklist check
        if result.code in self.code_blacklist:
            return True
        # Hide lengths (only for files, not dirs)
        if not result.is_directory and not result.is_listable:
            for lo, hi in self.hide_lengths:
                if lo <= result.size <= hi:
                    return True
        return False

    def add_result(self, result: ScanResult):
        with self.lock:
            if not self.should_hide(result):
                if not self.silent:
                    print(result.format_line(self.no_color, self.is_tty))
            self.results.append(result)

    def generate_report(self) -> str:
        output = []

        for uri in self.uris:
            base_url = normalize_to_dir(uri)
            output.append(f"Dirble Scan Report for {base_url}:")

            # Get results for this URI
            uri_results = [r for r in self.results if not self.should_hide(r) and r.url.startswith(base_url)]

            # Format tree
            tree = self._format_tree(base_url, uri_results)
            output.append(tree)

        return '\n'.join(output)

    def _format_tree(self, base_url: str, results: List[ScanResult]) -> str:
        indent = "  " if self.is_tty else ""
        nested = "    " if self.is_tty else ""

        # Get direct children
        files = [r for r in results if self._is_direct_child(r.url, base_url) and not r.is_directory and not r.is_listable]
        dirs = [r for r in results if self._is_direct_child(r.url, base_url) and (r.is_directory or r.is_listable)]

        output = []

        # Files first
        for f in files:
            output.append(f.format_line(self.no_color, self.is_tty, indent))

        # Directories
        for d in dirs:
            output.append("")
            output.append(d.format_line(self.no_color, self.is_tty, indent))

            # Children of this dir
            dir_files = [r for r in results if self._is_direct_child(r.url, d.url) and not r.is_directory and not r.is_listable]
            for f in dir_files:
                output.append(f.format_line(self.no_color, self.is_tty, nested))

            # Sub-directories
            sub_dirs = [r for r in results if self._is_direct_child(r.url, d.url) and (r.is_directory or r.is_listable)]
            for sd in sub_dirs:
                output.append("")
                inner = "    " if self.is_tty else ""
                output.append(sd.format_line(self.no_color, self.is_tty, inner))

                # Files in subdir
                sd_files = [r for r in results if self._is_direct_child(r.url, sd.url) and not r.is_directory and not r.is_listable]
                for f in sd_files:
                    deep = "      " if self.is_tty else ""
                    output.append(f.format_line(self.no_color, self.is_tty, deep))

            output.append("")

        return '\n'.join(output)

    def _is_direct_child(self, url: str, parent: str) -> bool:
        if not url.startswith(parent):
            return False
        rest = url[len(parent):]
        if url.endswith('/'):
            # Directory: rest should be "name/"
            name = rest.rstrip('/')
            return '/' not in name and name != ''
        else:
            # File: rest should not contain /
            return '/' not in rest and rest != ''

    def write_json(self, filename: str):
        visible = [r for r in self.results]
        if not visible:
            try:
                with open(filename, 'w') as f:
                    f.write('[]')
            except Exception as e:
                print(f"[ERROR] Failed to write JSON: {e}")
            return

        try:
            with open(filename, 'w') as f:
                f.write('[')
                for i, r in enumerate(visible):
                    obj = {
                        "url": r.url,
                        "code": r.code,
                        "size": r.size,
                        "is_directory": r.is_directory,
                        "is_listable": r.is_listable,
                        "redirect_url": r.redirect_url,
                        "found_from_listable": r.found_from_listable,
                    }
                    s = json.dumps(obj, separators=(',', ':'))
                    if i < len(visible) - 1:
                        f.write(s + ',\n')
                    else:
                        f.write(s + ']')
        except Exception as e:
            print(f"[ERROR] Failed to write JSON: {e}")

    def write_xml(self, filename: str):
        try:
            with open(filename, 'w') as f:
                f.write('<?xml version="1.0" encoding="UTF-8"?>\n<dirble_scan>\n')
                for r in self.results:
                    f.write(f'<path url="{r.url}" code="{r.code}" content_len="{r.size}" '
                           f'is_directory="{str(r.is_directory).lower()}" '
                           f'is_listable="{str(r.is_listable).lower()}" '
                           f'redirect_url="{r.redirect_url}" '
                           f'found_from_listable="{str(r.found_from_listable).lower()}"/>\n')
                f.write('</dirble_scan>')
        except Exception as e:
            print(f"[ERROR] Failed to write XML: {e}")

    def write_txt(self, filename: str):
        try:
            with open(filename, 'w') as f:
                report = self.generate_report_no_indent()
                f.write(report)
        except Exception as e:
            print(f"[ERROR] Failed to write TXT: {e}")

    def generate_report_no_indent(self) -> str:
        """Generate report without indentation (for file output)"""
        output = []

        for uri in self.uris:
            base_url = normalize_to_dir(uri)
            output.append(f"Dirble Scan Report for {base_url}:")

            uri_results = [r for r in self.results if not self.should_hide(r) and r.url.startswith(base_url)]

            tree = self._format_tree_no_indent(base_url, uri_results)
            output.append(tree)

        return '\n'.join(output)

    def _format_tree_no_indent(self, base_url: str, results: List[ScanResult]) -> str:
        files = [r for r in results if self._is_direct_child(r.url, base_url) and not r.is_directory and not r.is_listable]
        dirs = [r for r in results if self._is_direct_child(r.url, base_url) and (r.is_directory or r.is_listable)]

        output = []

        for f in files:
            output.append(f.format_line(True, False, ""))

        for d in dirs:
            output.append("")
            output.append(d.format_line(True, False, ""))

            dir_files = [r for r in results if self._is_direct_child(r.url, d.url) and not r.is_directory and not r.is_listable]
            for f in dir_files:
                output.append(f.format_line(True, False, ""))

            sub_dirs = [r for r in results if self._is_direct_child(r.url, d.url) and (r.is_directory or r.is_listable)]
            for sd in sub_dirs:
                output.append("")
                output.append(sd.format_line(True, False, ""))

                sd_files = [r for r in results if self._is_direct_child(r.url, sd.url) and not r.is_directory and not r.is_listable]
                for f in sd_files:
                    output.append(f.format_line(True, False, ""))

            output.append("")

        return '\n'.join(output)

def parse_hide_lengths(hide_list: List[str]) -> List[Tuple[int, int]]:
    ranges = []
    for item in hide_list:
        for part in item.split(','):
            part = part.strip()
            if '-' in part:
                lo, hi = part.split('-', 1)
                try:
                    ranges.append((int(lo), int(hi)))
                except ValueError:
                    pass
            else:
                try:
                    n = int(part)
                    ranges.append((n, n))
                except ValueError:
                    pass
    return ranges

def parse_codes(code_list: List[str]) -> List[int]:
    codes = []
    for item in code_list:
        for part in item.split(','):
            try:
                codes.append(int(part.strip()))
            except ValueError:
                pass
    return codes

class Scanner:
    def __init__(self, args, wordlist: List[str], extensions: List[str], 
                 prefixes: List[str], output: OutputManager):
        self.args = args
        self.wordlist = wordlist
        self.extensions = extensions
        self.prefixes = prefixes
        self.output = output
        self.max_threads = getattr(args, 'max_threads', 10)
        self.wordlist_split = getattr(args, 'wordlist_split', 3)
        self.scan_listable = getattr(args, 'scan_listable', False)
        self.scrape_listable = getattr(args, 'scrape_listable', False)
        self.disable_recursion = getattr(args, 'disable_recursion', False)
        self.max_recursion_depth = getattr(args, 'max_recursion_depth', None)
        self.force_extension = getattr(args, 'force_extension', False)
        self.ext_sub = getattr(args, 'ext_sub', False)
        self.show_htaccess = getattr(args, 'show_htaccess', False)
        self.disable_validator = getattr(args, 'disable_validator', False)
        self.scan_401 = getattr(args, 'scan_401', False)
        self.scan_403 = getattr(args, 'scan_403', False)

        # Build extension combos
        self.ext_combos = []
        if not self.force_extension:
            self.ext_combos.append(None)  # no extension
        for ext in self.extensions:
            self.ext_combos.append(ext)

    def scan_all(self, uris: List[str]):
        """Scan all URIs"""
        detect_client = HTTPClient(self.args)

        # Detection phase
        uri_info = []  # (uri, base_url, detection)
        for uri in uris:
            base_url = normalize_to_dir(uri)
            display_url = uri

            detection = None
            if not self.disable_validator and not self.output.code_whitelist:
                probe_base = uri if uri.endswith('/') else base_url
                detection = detect_not_found(detect_client, probe_base)

                if detection.redirect_dest:
                    print(f"[INFO] Detected nonexistent paths for {display_url} are (CODE:{detection.code}|DEST:{detection.redirect_dest})")
                else:
                    print(f"[INFO] Detected nonexistent paths for {display_url} are (CODE:{detection.code})")

            uri_info.append((uri, base_url, detection))

        # Scanning phase
        available = max(1, self.max_threads - 2)
        initial_split = max(available, self.wordlist_split)

        first_uri = True
        for uri, base_url, detection in uri_info:
            if first_uri and initial_split > self.wordlist_split:
                print(f"[INFO] Increasing wordlist-split for initial scan of {base_url} to {initial_split}")
            first_uri = False

            sub_dirs = self._scan_directory(
                base_url, detection, initial_split, depth=0, 
                found_from_listable=False
            )

            # Recursively scan subdirs
            self._process_subdirs(sub_dirs, depth=1)

    def _process_subdirs(self, subdirs: List[Dict], depth: int):
        for subdir in subdirs:
            url = subdir['url']

            if self.max_recursion_depth is not None and depth > self.max_recursion_depth:
                continue
            if self.disable_recursion:
                continue

            # Detect not-found for subdir
            detect_client = HTTPClient(self.args)
            detection = None
            if not self.disable_validator and not self.output.code_whitelist:
                detection = detect_not_found(detect_client, url)
                if detection.redirect_dest:
                    print(f"[INFO] Detected nonexistent paths for {url} are (CODE:{detection.code}|DEST:{detection.redirect_dest})")
                else:
                    print(f"[INFO] Detected nonexistent paths for {url} are (CODE:{detection.code})")

            new_subdirs = self._scan_directory(
                url, detection, self.wordlist_split, 
                depth=depth, 
                found_from_listable=subdir['found_from_listable']
            )

            self._process_subdirs(new_subdirs, depth + 1)

    def _scan_directory(self, base_url: str, detection: Optional[NotFoundDetection],
                        split: int, depth: int, found_from_listable: bool) -> List[Dict]:
        """Scan a directory, return discovered subdirectories"""
        discovered = []
        discovered_lock = threading.Lock()

        handles = []

        for ext in self.ext_combos:
            # Split wordlist
            chunks = self._split_wordlist(self.wordlist, split)

            for chunk in chunks:
                h = threading.Thread(
                    target=self._scan_chunk,
                    args=(base_url, ext, chunk, detection, discovered, discovered_lock,
                          depth, found_from_listable),
                    daemon=True
                )
                h.start()
                handles.append(h)

        for h in handles:
            h.join()

        return discovered

    def _scan_chunk(self, base_url: str, ext: Optional[str], words: List[str],
                    detection: Optional[NotFoundDetection], 
                    discovered: List[Dict], discovered_lock: threading.Lock,
                    depth: int, found_from_listable: bool):
        """Scan a chunk of words"""
        thread_name = threading.current_thread().name

        if VERBOSE_LEVEL >= 1:
            tid = threading.current_thread().ident
            ts = time.strftime("%H:%M:%S")
            print(f"{ts} [DEBUG] ({tid}) dirble::request_thread: Scanning {base_url}")

        client = HTTPClient(self.args)

        for word in words:
            # Handle %EXT% substitution
            if self.ext_sub:
                if ext is not None:
                    if '%EXT%' in word:
                        ext_no_dot = ext.lstrip('.')
                        actual_words = [(word.replace('%EXT%', ext_no_dot), None)]
                    else:
                        actual_words = [(word, ext)]
                else:
                    if '%EXT%' in word:
                        continue  # Skip words with %EXT% when no extension
                    actual_words = [(word, None)]
            else:
                actual_words = [(word, ext)]

            for base_word, ext_to_add in actual_words:
                # Apply prefixes
                if self.prefixes:
                    word_variants = [p + base_word for p in self.prefixes]
                else:
                    word_variants = [base_word]

                for test_word in word_variants:
                    if ext_to_add is None:
                        # No extension - check as both file and directory
                        bare_url = base_url + test_word
                        dir_url = bare_url + '/'

                        # Check bare URL
                        bare_resp = client.request(bare_url, False)
                        if VERBOSE_LEVEL >= 2:
                            tid = threading.current_thread().ident
                            ts = time.strftime("%H:%M:%S")
                            if bare_resp:
                                print(f"{ts} [TRACE] ({tid}) dirble::request: [src/request.rs:114] Requesting {bare_url}")

                        # Check directory URL
                        dir_resp = client.request(dir_url, True)

                        if dir_resp is not None:
                            if detection and detection.matches(dir_resp):
                                if VERBOSE_LEVEL >= 2:
                                    tid = threading.current_thread().ident
                                    ts = time.strftime("%H:%M:%S")
                                    print(f"{ts} [TRACE] ({tid}) dirble::request_thread: [src/request_thread.rs:179] [{bare_url}]: matches Not Found condition")
                                # Not found as directory, check if found as file
                                if bare_resp and (not detection or not detection.matches(bare_resp)):
                                    self._process_file_response(bare_url, bare_resp, detection, 
                                                                 discovered, discovered_lock, depth, found_from_listable)
                            else:
                                # Found as directory
                                self._process_dir_response(dir_url, dir_resp, detection,
                                                           discovered, discovered_lock, depth, found_from_listable)
                        elif bare_resp is not None:
                            if detection and detection.matches(bare_resp):
                                if VERBOSE_LEVEL >= 2:
                                    tid = threading.current_thread().ident
                                    ts = time.strftime("%H:%M:%S")
                                    print(f"{ts} [TRACE] ({tid}) dirble::request_thread: [src/request_thread.rs:179] [{bare_url}]: matches Not Found condition")
                            else:
                                self._process_file_response(bare_url, bare_resp, detection,
                                                           discovered, discovered_lock, depth, found_from_listable)
                    else:
                        # Extension - check as file only
                        file_url = base_url + test_word + ext_to_add
                        resp = client.request(file_url, True)

                        if resp is None:
                            continue

                        if detection and detection.matches(resp):
                            if VERBOSE_LEVEL >= 2:
                                tid = threading.current_thread().ident
                                ts = time.strftime("%H:%M:%S")
                                print(f"{ts} [TRACE] ({tid}) dirble::request_thread: [src/request_thread.rs:179] [{file_url}]: matches Not Found condition")
                            continue

                        self._process_file_response(file_url, resp, detection,
                                                    discovered, discovered_lock, depth, found_from_listable)

        if VERBOSE_LEVEL >= 1:
            tid = threading.current_thread().ident
            ts = time.strftime("%H:%M:%S")
            print(f"{ts} [DEBUG] ({tid}) dirble::request_thread: Finished scanning {base_url}")

    def _process_dir_response(self, url: str, resp: Dict, detection: Optional[NotFoundDetection],
                               discovered: List[Dict], discovered_lock: threading.Lock,
                               depth: int, found_from_listable: bool):
        code = resp['code']
        size = resp['size']
        body = resp.get('body', '')
        redirect_url = resp.get('redirect_url', '')

        # Filter by code
        if not self.output.code_whitelist and not (200 <= code <= 299) and code != 301 and code != 302 and code != 403:
            return

        if self.output.code_whitelist and code not in self.output.code_whitelist:
            return
        if code in self.output.code_blacklist:
            return

        # Detect if listable
        is_listable = False
        if body:
            is_listable = is_directory_listing(body)

        result = ScanResult(url, code, size, True, is_listable, redirect_url, found_from_listable)
        self.output.add_result(result)

        # Add to discovered for recursion
        should_scan = True

        # For listable dirs, only recurse if scan_listable or scrape_listable
        if is_listable and not self.scan_listable:
            should_scan = False

        # Check auth codes
        if code == 401 and not self.scan_401:
            should_scan = False
        if code == 403 and not self.scan_403:
            should_scan = False

        if should_scan and not self.disable_recursion:
            if self.max_recursion_depth is None or depth < self.max_recursion_depth:
                with discovered_lock:
                    discovered.append({
                        'url': url,
                        'depth': depth + 1,
                        'found_from_listable': found_from_listable,
                        'is_listable': is_listable,
                    })

        # Scrape listable directory
        if is_listable and self.scrape_listable and body:
            scraped = scrape_urls_from_listing(body, url)
            if VERBOSE_LEVEL >= 2:
                for su in scraped:
                    tid = threading.current_thread().ident
                    ts = time.strftime("%H:%M:%S")
                    print(f"{ts} [TRACE] ({tid}) dirble::request_thread: [src/request_thread.rs:174] [{su}]: code 0 detected")

            for su in scraped:
                if su.endswith('/'):
                    sub_result = ScanResult(su, 200, 0, True, False, "", True)
                    # We'd need to check these, but for now just add to discovered
                    with discovered_lock:
                        discovered.append({
                            'url': su,
                            'depth': depth + 1,
                            'found_from_listable': True,
                            'is_listable': False,
                        })

    def _process_file_response(self, url: str, resp: Dict, detection: Optional[NotFoundDetection],
                                discovered: List[Dict], discovered_lock: threading.Lock,
                                depth: int, found_from_listable: bool):
        code = resp['code']
        size = resp['size']
        redirect_url = resp.get('redirect_url', '')

        # Filter 404s unless whitelisted or validator disabled
        if code == 404 and not self.output.code_whitelist and not self.disable_validator:
            return

        if self.output.code_whitelist and code not in self.output.code_whitelist:
            return
        if code in self.output.code_blacklist:
            return

        # .ht* filter
        if code == 403 and not self.show_htaccess:
            path_parts = url.split('/')
            last_part = path_parts[-1] if path_parts else ''
            if last_part.startswith('.ht'):
                return

        result = ScanResult(url, code, size, False, False, redirect_url, found_from_listable)
        self.output.add_result(result)

    def _split_wordlist(self, wordlist: List[str], n: int) -> List[List[str]]:
        n = max(1, n)
        total = len(wordlist)

        # Create n chunks, distributing words round-robin
        chunks = [[] for _ in range(n)]
        for i, word in enumerate(wordlist):
