def detect_not_found(client: HTTPClient, base_url: str) -> NotFoundDetection:
    """Probe for the 'not found' code at base_url"""
    probe_lengths = [10, 20, 30]
    codes = []
    dests = []

    for length in probe_lengths:
        probe_path = random_string(length)
        probe_url = base_url + probe_path

        resp = client.request(probe_url, False)
        if resp:
            codes.append(resp['code'])
            dests.append(resp.get('redirect_url', ''))
        else:
            codes.append(0)
            dests.append('')

    if not codes:
        return NotFoundDetection(404)

    # Find majority code
    first = codes[0]
    if all(c == first for c in codes):
        code = first
    else:
        from collections import Counter
        count = Counter(codes)
        code = count.most_common(1)[0][0]

    # For redirects, check consistent destination
    redirect_dest = ""
    if 300 <= code <= 399:
        non_empty = [d for d in dests if d]
        if non_empty and all(d == non_empty[0] for d in non_empty):
            redirect_dest = non_empty[0]

    return NotFoundDetection(code, redirect_dest)

