def normalize_to_dir(uri: str) -> str:
    """Normalize a URI to a directory URL (with trailing slash)"""
    if uri.endswith('/'):
        return uri

    parsed = urllib.parse.urlparse(uri)
    path = parsed.path

    if not path or path == '/':
        return uri + '/'

    # Strip last path component
    parent = path.rsplit('/', 1)[0] + '/'
    if parent == '/':
        result = urllib.parse.urlunparse((parsed.scheme, parsed.netloc, '/', 
                                          parsed.params, parsed.query, parsed.fragment))
    else:
        result = urllib.parse.urlunparse((parsed.scheme, parsed.netloc, parent,
                                          parsed.params, parsed.query, parsed.fragment))
    return result

