def normalize_to_dir(uri: str) -> str:
    """Normalize a URI to a directory URL (with trailing slash)"""
    if uri.endswith('/'):
        return uri

    parsed = urllib.parse.urlparse(uri)
    path = parsed.path

    if not path or path == '/':
        # Just add trailing slash
        return urllib.parse.urlunparse((parsed.scheme, parsed.netloc, '/',
                                       parsed.params, parsed.query, parsed.fragment))

    # Strip last path component to get parent directory
    if '/' in path:
        parent = path.rsplit('/', 1)[0] + '/'
    else:
        parent = '/'

    return urllib.parse.urlunparse((parsed.scheme, parsed.netloc, parent,
                                    parsed.params, parsed.query, parsed.fragment))


def parse_hide_lengths(hide_list: List[str]) -> List[Tuple[int, int]]:
    ranges = []
    for item in hide_list:
        for part in item.split(','):
            part = part.strip()
            if '-' in part:
                lo, hi = part.split('-', 1)
                try:
                    ranges.append((int(lo), int(hi)))
                except ValueError:
                    pass
            else:
                try:
                    n = int(part)
                    ranges.append((n, n))
                except ValueError:
                    pass
    return ranges


def parse_codes(code_list: List[str]) -> List[int]:
    codes = []
    for item in code_list:
        for part in item.split(','):
            try:
                codes.append(int(part.strip()))
            except ValueError:
                pass
    return codes


