        if tag == 'a':
            for attr, value in attrs:
                if attr == 'href' and value:
                    if value in ('/', '../', '#') or value.startswith('?') or value.startswith('#'):
                        continue
                    if value.startswith('http://') or value.startswith('https://'):
                        self.links.append(value)
                    else:
                        try:
                            resolved = urllib.parse.urljoin(self.base_url, value)
                            self.links.append(resolved)
                        except Exception:
                            pass


def is_directory_listing(body: str) -> bool:
    patterns = [
        "Index of /",
        "Directory listing for /",
        "<title>Directory listing",
        "Parent Directory",
        "[PARENTDIR]",
        "Directory Listing",
    ]
    for pattern in patterns:
        if pattern in body:
            return True
    return False


def scrape_urls_from_listing(body: str, base_url: str) -> List[str]:
    parser = DirectoryListingParser(base_url)
    try:
        parser.feed(body)
    except Exception:
        pass
    seen = set()
    result = []
    for link in parser.links:
        if link not in seen:
            seen.add(link)
            result.append(link)
    return result


def normalize_to_dir(uri: str) -> str:
    """Normalize a URI to a directory URL (with trailing slash)"""
    if uri.endswith('/'):
        return uri

    parsed = urllib.parse.urlparse(uri)
    path = parsed.path

    if not path or path == '/':
        # Just add trailing slash
        return urllib.parse.urlunparse((parsed.scheme, parsed.netloc, '/',
                                       parsed.params, parsed.query, parsed.fragment))

    # Strip last path component to get parent directory
    if '/' in path:
        parent = path.rsplit('/', 1)[0] + '/'
    else:
        parent = '/'

    return urllib.parse.urlunparse((parsed.scheme, parsed.netloc, parent,
                                    parsed.params, parsed.query, parsed.fragment))


def parse_hide_lengths(hide_list: List[str]) -> List[Tuple[int, int]]:
    ranges = []
    for item in hide_list:
        for part in item.split(','):
            part = part.strip()
            if '-' in part:
                lo, hi = part.split('-', 1)
                try:
                    ranges.append((int(lo), int(hi)))
                except ValueError:
                    pass
            else:
                try:
                    n = int(part)
                    ranges.append((n, n))
                except ValueError:
                    pass
    return ranges


def parse_codes(code_list: List[str]) -> List[int]:
    codes = []
    for item in code_list:
        for part in item.split(','):
            try:
                codes.append(int(part.strip()))
            except ValueError:
                pass
    return codes


class HTTPClient:
    def __init__(self, args):
        self.timeout = getattr(args, 'timeout', 5)
        self.verb = getattr(args, 'verb', 'get').upper()
        self.user_agent = getattr(args, 'user_agent', None)
        self.cookies = getattr(args, 'cookies', [])
        self.custom_headers = getattr(args, 'header', [])
        self.ignore_cert = getattr(args, 'ignore_cert', False)
        self.no_proxy = getattr(args, 'no_proxy', False)
        self.throttle = getattr(args, 'throttle', None)
        self.username = getattr(args, 'username', None)
        self.password = getattr(args, 'password', None)
        self.max_errors = getattr(args, 'max_errors', 5)
        self.proxy = None

        if getattr(args, 'burp', False):
            self.proxy = "http://localhost:8080"
        elif getattr(args, 'proxy', None):
            self.proxy = args.proxy

        self._error_count = 0
        self._verbose = getattr(args, 'verbose', 0)

    def request(self, url: str, get_body: bool = True) -> Optional[Dict]:
        """Make an HTTP request"""
        if self._verbose >= 2:
            tid = get_thread_id()
            ts = get_timestamp()
            print(f"{ts} [TRACE] ({tid}) dirble::request: [src/request.rs:114] Requesting {url}")

        if self.throttle:
            time.sleep(self.throttle / 1000.0)

        # Extract credentials from URL
        parsed = urllib.parse.urlparse(url)
        username = parsed.username or self.username
        password = parsed.password or self.password

        # Clean URL (remove credentials)
        if parsed.username or parsed.password:
            netloc = parsed.hostname
            if parsed.port:
                netloc += f":{parsed.port}"
            clean_url = urllib.parse.urlunparse((parsed.scheme, netloc, parsed.path,
                                                 parsed.params, parsed.query, parsed.fragment))
        else:
            clean_url = url

        # Build request
        req = urllib.request.Request(clean_url, method=self.verb)

        # Add auth
        if username:
            import base64
            creds = base64.b64encode(f"{username}:{password or ''}".encode()).decode()
            req.add_header('Authorization', f'Basic {creds}')

        # Add user agent
        if self.user_agent:
            req.add_header('User-Agent', self.user_agent)

        # Add cookies
        if self.cookies:
            cookie_str = '; '.join(self.cookies)
            req.add_header('Cookie', cookie_str)

        # Add custom headers
        for header in self.custom_headers:
            if ':' in header:
                name, _, value = header.partition(':')
                req.add_header(name.strip(), value.strip())

        # SSL context
        ssl_ctx = ssl.create_default_context()
        if self.ignore_cert:
            ssl_ctx.check_hostname = False
            ssl_ctx.verify_mode = ssl.CERT_NONE

        # Build opener
        class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, req, fp, code, msg, headers, newurl):
                return None

        handlers = [NoRedirectHandler(), urllib.request.HTTPSHandler(context=ssl_ctx)]
        if self.proxy and not self.no_proxy:
            handlers.append(urllib.request.ProxyHandler({'http': self.proxy, 'https': self.proxy}))
        elif self.no_proxy:
            handlers.append(urllib.request.ProxyHandler({}))

        opener = urllib.request.build_opener(*handlers)

        try:
            with opener.open(req, timeout=self.timeout) as resp:
                code = resp.status
                content_len_hdr = resp.headers.get('Content-Length')
                redirect_url = ""

                body = None
                if get_body and self.verb != 'HEAD':
                    body_bytes = resp.read()
                    body = body_bytes.decode('utf-8', errors='replace')
                    if content_len_hdr:
                        try:
                            content_len = int(content_len_hdr)
                        except ValueError:
                            content_len = len(body)
                    else:
                        content_len = len(body)
                else:
                    resp.read()
                    content_len = int(content_len_hdr) if content_len_hdr else 0
                    try:
                        content_len = int(content_len_hdr) if content_len_hdr else 0
                    except (ValueError, TypeError):
                        content_len = 0

                self._error_count = 0
                return {
                    'code': code,
                    'size': content_len,
                    'redirect_url': redirect_url,
                    'body': body,
                }
        except urllib.error.HTTPError as e:
            code = e.code
            content_len_hdr = e.headers.get('Content-Length')
            redirect_url = ""

            if 300 <= code <= 399:
                loc = e.headers.get('Location', '')
                if loc:
                    if loc.startswith('http://') or loc.startswith('https://'):
                        redirect_url = loc
                    else:
                        try:
                            redirect_url = urllib.parse.urljoin(url, loc)
                        except Exception:
                            redirect_url = loc

            body = None
            content_len = 0
            if get_body and self.verb != 'HEAD':
                try:
                    body_bytes = e.read()
                    body = body_bytes.decode('utf-8', errors='replace')
                    if content_len_hdr:
                        try:
                            content_len = int(content_len_hdr)
                        except ValueError:
                            content_len = len(body)
                    else:
                        content_len = len(body)
                except Exception:
                    pass
            else:
                try:
                    e.read()
                except Exception:
                    pass
                try:
                    content_len = int(content_len_hdr) if content_len_hdr else 0
                except (ValueError, TypeError):
                    content_len = 0

            self._error_count = 0
            return {
                'code': code,
                'size': content_len,
                'redirect_url': redirect_url,
                'body': body,
            }
        except (urllib.error.URLError, socket.timeout, ConnectionResetError, OSError, Exception) as e:
            self._error_count += 1
            return None


class NotFoundDetection:
    def __init__(self, code: int, redirect_dest: str = ""):
        self.code = code
        self.redirect_dest = redirect_dest

    def matches(self, resp: Dict) -> bool:
        if resp['code'] != self.code:
            return False
        if self.redirect_dest:
            if resp.get('redirect_url', '') != self.redirect_dest:
                return False
        return True


def detect_not_found(client: HTTPClient, base_url: str) -> NotFoundDetection:
    """Probe for the 'not found' code at base_url"""
    probe_lengths = [10, 20, 30]
    codes = []
    dests = []

    for length in probe_lengths:
        probe_path = random_string(length)
        probe_url = base_url + probe_path

        resp = client.request(probe_url, False)
        if resp:
            codes.append(resp['code'])
            dests.append(resp.get('redirect_url', ''))
        else:
            codes.append(0)
            dests.append('')

    if not codes:
        return NotFoundDetection(404)

    # Find majority code
    count = Counter(codes)
    code = count.most_common(1)[0][0]

    # For redirects, check consistent destination
    redirect_dest = ""
    if 300 <= code <= 399:
        non_empty = [d for d in dests if d]
        if non_empty and all(d == non_empty[0] for d in non_empty):
            redirect_dest = non_empty[0]

    return NotFoundDetection(code, redirect_dest)


