class OutputManager:
    def __init__(self, args, uris: List[str]):
        self.args = args
        self.uris = uris
        self.results = []
        self.lock = threading.Lock()
        self.use_tty = cached_is_tty()

        self.hide_lengths = parse_hide_lengths(getattr(args, 'hide_lengths', []))
        self.code_blacklist = parse_codes(getattr(args, 'code_blacklist', []))
        self.code_whitelist = parse_codes(getattr(args, 'code_whitelist', []))
        self.no_color = getattr(args, 'no_color', False)
        self.silent = getattr(args, 'silent', False)

    def should_hide(self, result: ScanResult) -> bool:
        # Whitelist check
        if self.code_whitelist and result.code not in self.code_whitelist:
            return True
        # Blacklist check
        if result.code in self.code_blacklist:
            return True
        # Hide lengths (only for files, not dirs)
        if not result.is_directory and not result.is_listable:
            for lo, hi in self.hide_lengths:
                if lo <= result.size <= hi:
                    return True
        return False

    def add_result(self, result: ScanResult):
        with self.lock:
            if not self.should_hide(result):
                if not self.silent:
                    print(result.format_line(self.no_color, self.use_tty))
            self.results.append(result)

    def _is_direct_child(self, url: str, parent: str) -> bool:
        if not url.startswith(parent):
            return False
        rest = url[len(parent):]
        if url.endswith('/'):
            # Directory: rest should be "name/"
            name = rest.rstrip('/')
            return '/' not in name and name != ''
        else:
            # File: rest should not contain /
            return '/' not in rest and rest != ''

    def generate_text_report(self, use_indent: bool) -> str:
        indent = "  " if use_indent else ""
        nested = "    " if use_indent else ""

        output = []

        for uri in self.uris:
            base_url = normalize_to_dir(uri)
            output.append(f"Dirble Scan Report for {base_url}:")

            # Get visible results for this URI
            uri_results = [r for r in self.results 
                          if not self.should_hide(r) and r.url.startswith(base_url)]

            # Build tree
            tree = self._format_tree(base_url, uri_results, indent, nested)
            output.append(tree)

        return '\n'.join(output)

    def _format_tree(self, base_url: str, results: List[ScanResult], 
                     indent: str, nested: str) -> str:
        # Get direct children
        files = [r for r in results 
                if self._is_direct_child(r.url, base_url) and not r.is_directory and not r.is_listable]
        dirs = [r for r in results 
               if self._is_direct_child(r.url, base_url) and (r.is_directory or r.is_listable)]

        output = []

        # Files first
        for f in files:
            output.append(f.format_line(self.no_color, self.use_tty, indent))

        # Directories
        for d in dirs:
            output.append("")
            output.append(d.format_line(self.no_color, self.use_tty, indent))

            # Children of this dir
            dir_files = [r for r in results 
                        if self._is_direct_child(r.url, d.url) and not r.is_directory and not r.is_listable]
            for f in dir_files:
                output.append(f.format_line(self.no_color, self.use_tty, nested))

            # Sub-directories (simplistic depth-2 handling)
            sub_dirs = [r for r in results 
                       if self._is_direct_child(r.url, d.url) and (r.is_directory or r.is_listable)]
            for sd in sub_dirs:
                output.append("")
                output.append(sd.format_line(self.no_color, self.use_tty, nested))

                # Files in subdir
                sd_files = [r for r in results 
                           if self._is_direct_child(r.url, sd.url) and not r.is_directory and not r.is_listable]
                deep = "    " + nested if self.use_tty else ""
                for f in sd_files:
                    output.append(f.format_line(self.no_color, self.use_tty, deep))

            output.append("")

        return '\n'.join(output)

    def write_json(self, filename: str):
        try:
            with open(filename, 'w') as f:
                if not self.results:
                    f.write('[]')
                    return

                last_idx = len(self.results) - 1
                f.write('[')
                for i, r in enumerate(self.results):
                    obj = {
                        "url": r.url,
                        "code": r.code,
                        "size": r.size,
                        "is_directory": r.is_directory,
                        "is_listable": r.is_listable,
                        "redirect_url": r.redirect_url,
                        "found_from_listable": r.found_from_listable,
                    }
                    s = json.dumps(obj, separators=(',', ':'))
                    if i < last_idx:
                        f.write(s + ',\n')
                    else:
                        f.write(s + ']')
        except Exception as e:
            print(f"[ERROR] Failed to write JSON: {e}")

    def write_xml(self, filename: str):
        try:
            with open(filename, 'w') as f:
                f.write('<?xml version="1.0" encoding="UTF-8"?>\n<dirble_scan>\n')
                for r in self.results:
                    f.write(f'<path url="{r.url}" code="{r.code}" content_len="{r.size}" '
                           f'is_directory="{str(r.is_directory).lower()}" '
                           f'is_listable="{str(r.is_listable).lower()}" '
                           f'redirect_url="{r.redirect_url}" '
                           f'found_from_listable="{str(r.found_from_listable).lower()}"/>\n')
                f.write('</dirble_scan>')
        except Exception as e:
            print(f"[ERROR] Failed to write XML: {e}")

    def write_txt(self, filename: str):
        try:
            with open(filename, 'w') as f:
                report = self.generate_text_report(False)
                f.write(report)
        except Exception as e:
            print(f"[ERROR] Failed to write TXT: {e}")


class Scanner:
    def __init__(self, args, wordlist: List[str], extensions: List[str],
                 prefixes: List[str], output: OutputManager):
        self.args = args
        self.wordlist = wordlist
        self.extensions = extensions
        self.prefixes = prefixes
        self.output = output
        self.max_threads = getattr(args, 'max_threads', 10)
        self.wordlist_split = getattr(args, 'wordlist_split', 3)
        self.scan_listable = getattr(args, 'scan_listable', False)
        self.scrape_listable = getattr(args, 'scrape_listable', False)
        self.disable_recursion = getattr(args, 'disable_recursion', False)
        self.max_recursion_depth = getattr(args, 'max_recursion_depth', None)
        self.force_extension = getattr(args, 'force_extension', False)
        self.ext_sub = getattr(args, 'ext_sub', False)
        self.show_htaccess = getattr(args, 'show_htaccess', False)
        self.disable_validator = getattr(args, 'disable_validator', False)
        self.scan_401 = getattr(args, 'scan_401', False)
        self.scan_403 = getattr(args, 'scan_403', False)

        # Build extension combos: None = no extension
        self.ext_combos: List[Optional[str]] = []
        if not self.force_extension:
            self.ext_combos.append(None)
        for ext in self.extensions:
            self.ext_combos.append(ext)

    def make_client(self) -> HTTPClient:
        return HTTPClient(self.args)

    def scan_all(self, uris: List[str]):
        """Scan all URIs"""
        detect_client = self.make_client()

        # Detection phase for all URIs
        uri_info = []  # (uri, base_url, detection)
        for uri in uris:
            base_url = normalize_to_dir(uri)
            display_url = uri

            detection = None
            if not self.disable_validator and not self.output.code_whitelist:
                probe_base = uri if uri.endswith('/') else base_url
                detection = detect_not_found(detect_client, probe_base)

                if detection.redirect_dest:
                    print_info(f"Detected nonexistent paths for {display_url} are (CODE:{detection.code}|DEST:{detection.redirect_dest})")
                else:
                    print_info(f"Detected nonexistent paths for {display_url} are (CODE:{detection.code})")

            uri_info.append((uri, base_url, detection))

        # Calculate initial split
        available = max(1, self.max_threads - 2)
        initial_split = max(available, self.wordlist_split)

        # Scan each URI
        first_uri = True
        for uri, base_url, detection in uri_info:
            if first_uri and initial_split > self.wordlist_split:
                print_info(f"Increasing wordlist-split for initial scan of {base_url} to {initial_split}")
            first_uri = False

            sub_dirs = self._scan_directory(
                base_url, detection, initial_split, depth=0,
                found_from_listable=False
            )

            # Recursively process subdirs
            self._process_subdirs(sub_dirs, depth=1)

    def _process_subdirs(self, subdirs: List[Dict], depth: int):
        for subdir in subdirs:
            url = subdir['url']

            if self.disable_recursion:
                continue
            if self.max_recursion_depth is not None and depth > self.max_recursion_depth:
                continue

            # Detect not-found for subdir
            detect_client = self.make_client()
            detection = None
            if not self.disable_validator and not self.output.code_whitelist:
                detection = detect_not_found(detect_client, url)
                if detection.redirect_dest:
                    print_info(f"Detected nonexistent paths for {url} are (CODE:{detection.code}|DEST:{detection.redirect_dest})")
                else:
                    print_info(f"Detected nonexistent paths for {url} are (CODE:{detection.code})")

            new_subdirs = self._scan_directory(
                url, detection, self.wordlist_split,
                depth=depth, found_from_listable=subdir['found_from_listable']
            )

            self._process_subdirs(new_subdirs, depth + 1)

    def _scan_directory(self, base_url: str, detection: Optional[NotFoundDetection],
                        split: int, depth: int, found_from_listable: bool) -> List[Dict]:
        """Scan a directory, return discovered subdirectories"""
        discovered = []
        discovered_lock = threading.Lock()

        handles = []

        for ext in self.ext_combos:
            chunks = self._split_wordlist(self.wordlist, split)

            for chunk in chunks:
                h = threading.Thread(
                    target=self._scan_chunk,
                    args=(base_url, ext, chunk, detection, discovered, discovered_lock,
                          depth, found_from_listable),
                    daemon=True
                )
                h.start()
                handles.append(h)

        for h in handles:
            h.join()

        return discovered

    def _scan_chunk(self, base_url: str, ext: Optional[str], words: List[str],
                    detection: Optional[NotFoundDetection],
                    discovered: List[Dict], discovered_lock: threading.Lock,
                    depth: int, found_from_listable: bool):
        """Scan a chunk of the wordlist"""
        client = self.make_client()

        print_debug(f"Scanning {base_url}")

        for word in words:
            # Handle %EXT% substitution
            if self.ext_sub:
                if ext is not None:
                    ext_no_dot = ext.lstrip('.')
                    if '%EXT%' in word:
                        final_word = word.replace('%EXT%', ext_no_dot)
                        final_ext = None  # ext already applied
                    else:
                        final_word = word
                        final_ext = ext
                else:
                    if '%EXT%' in word:
                        continue  # Skip %EXT% words when no extension
                    final_word = word
                    final_ext = None
            else:
                final_word = word
                final_ext = ext

            # Apply prefixes
            if self.prefixes:
                prefixed_words = [p + final_word for p in self.prefixes]
            else:
                prefixed_words = [final_word]

            for test_word in prefixed_words:
                if final_ext is None:
                    # No extension: check bare URL, then if not-found check directory URL
                    bare_url = base_url + test_word

                    bare_resp = client.request(bare_url, False)

                    if bare_resp is None:
                        # Network error - skip
                        continue

                    # Check if bare URL matches not-found
                    if detection and detection.matches(bare_resp):
                        print_trace_notfound(bare_url)
                        # Don't check directory version
                        continue

                    # Bare URL returned something interesting - also check directory version
                    dir_url = bare_url + '/'
                    dir_resp = client.request(dir_url, True)

                    if dir_resp is None:
                        # Bare URL was interesting but dir failed
                        # Report as file
                        self._emit_file(bare_url, bare_resp, detection, 
                                       discovered, discovered_lock, depth, found_from_listable)
                        continue

                    # Check if directory version matches not-found
                    if detection and detection.matches(dir_resp):
                        # Directory not found, but bare URL was interesting
                        self._emit_file(bare_url, bare_resp, detection,
                                       discovered, discovered_lock, depth, found_from_listable)
                    else:
                        # Directory found
                        body = dir_resp.get('body', '')
                        is_listing = bool(body) and is_directory_listing(body)
                        self._emit_dir(dir_url, dir_resp, is_listing,
                                      discovered, discovered_lock, depth, found_from_listable)
                else:
                    # Extension: just check as file
                    file_url = base_url + test_word + final_ext

                    resp = client.request(file_url, True)

                    if resp is None:
                        continue

                    if detection and detection.matches(resp):
                        print_trace_notfound(file_url)
                        continue

                    self._emit_file(file_url, resp, detection,
                                   discovered, discovered_lock, depth, found_from_listable)

        print_debug(f"Finished scanning {base_url}")

    def _emit_file(self, url: str, resp: Dict, detection: Optional[NotFoundDetection],
                   discovered: List[Dict], discovered_lock: threading.Lock,
                   depth: int, found_from_listable: bool):
        code = resp['code']
        size = resp['size']
        redirect_url = resp.get('redirect_url', '')

        # Filter 404 unless whitelisted or validator disabled
        if code == 404 and not self.output.code_whitelist and not self.disable_validator:
