    ranges = []
    for item in hide_list:
        for part in item.split(','):
            part = part.strip()
            if '-' in part:
                lo, hi = part.split('-', 1)
                try:
                    ranges.append((int(lo), int(hi)))
                except ValueError:
                    pass
            else:
                try:
                    n = int(part)
                    ranges.append((n, n))
                except ValueError:
                    pass
    return ranges


