class OutputManager:
    def __init__(self, args, uris: List[str]):
        self.args = args
        self.uris = uris
        self.results = []
        self.lock = threading.Lock()
        self.use_tty = cached_is_tty()

        self.hide_lengths = parse_hide_lengths(getattr(args, 'hide_lengths', []))
        self.code_blacklist = parse_codes(getattr(args, 'code_blacklist', []))
        self.code_whitelist = parse_codes(getattr(args, 'code_whitelist', []))
        self.no_color = getattr(args, 'no_color', False)
        self.silent = getattr(args, 'silent', False)

    def should_hide(self, result: ScanResult) -> bool:
        # Whitelist check
        if self.code_whitelist and result.code not in self.code_whitelist:
            return True
        # Blacklist check
        if result.code in self.code_blacklist:
            return True
        # Hide lengths (only for files, not dirs)
        if not result.is_directory and not result.is_listable:
            for lo, hi in self.hide_lengths:
                if lo <= result.size <= hi:
                    return True
        return False

    def add_result(self, result: ScanResult):
        with self.lock:
            if not self.should_hide(result):
                if not self.silent:
                    print(result.format_line(self.no_color, self.use_tty))
            self.results.append(result)

    def _is_direct_child(self, url: str, parent: str) -> bool:
        if not url.startswith(parent):
            return False
        rest = url[len(parent):]
        if url.endswith('/'):
            # Directory: rest should be "name/"
            name = rest.rstrip('/')
            return '/' not in name and name != ''
        else:
            # File: rest should not contain /
            return '/' not in rest and rest != ''

    def generate_text_report(self, use_indent: bool) -> str:
        indent = "  " if use_indent else ""
        nested = "    " if use_indent else ""

        output = []

        for uri in self.uris:
            base_url = normalize_to_dir(uri)
            output.append(f"Dirble Scan Report for {base_url}:")

            # Get visible results for this URI
            uri_results = [r for r in self.results 
                          if not self.should_hide(r) and r.url.startswith(base_url)]

            # Build tree
            tree = self._format_tree(base_url, uri_results, indent, nested)
            output.append(tree)

        return '\n'.join(output)

    def _format_tree(self, base_url: str, results: List[ScanResult], 
                     indent: str, nested: str) -> str:
        # Get direct children
        files = [r for r in results 
                if self._is_direct_child(r.url, base_url) and not r.is_directory and not r.is_listable]
        dirs = [r for r in results 
               if self._is_direct_child(r.url, base_url) and (r.is_directory or r.is_listable)]

        output = []

        # Files first
        for f in files:
            output.append(f.format_line(self.no_color, self.use_tty, indent))

        # Directories
        for d in dirs:
            output.append("")
            output.append(d.format_line(self.no_color, self.use_tty, indent))

            # Children of this dir
            dir_files = [r for r in results 
                        if self._is_direct_child(r.url, d.url) and not r.is_directory and not r.is_listable]
            for f in dir_files:
                output.append(f.format_line(self.no_color, self.use_tty, nested))

            # Sub-directories (simplistic depth-2 handling)
            sub_dirs = [r for r in results 
                       if self._is_direct_child(r.url, d.url) and (r.is_directory or r.is_listable)]
            for sd in sub_dirs:
                output.append("")
                output.append(sd.format_line(self.no_color, self.use_tty, nested))

                # Files in subdir
                sd_files = [r for r in results 
                           if self._is_direct_child(r.url, sd.url) and not r.is_directory and not r.is_listable]
                deep = "    " + nested if self.use_tty else ""
                for f in sd_files:
                    output.append(f.format_line(self.no_color, self.use_tty, deep))

            output.append("")

        return '\n'.join(output)

    def write_json(self, filename: str):
        try:
            with open(filename, 'w') as f:
