                        "size": r.size,
                        "is_directory": r.is_directory,
                        "is_listable": r.is_listable,
                        "redirect_url": r.redirect_url,
                        "found_from_listable": r.found_from_listable,
                    }
                    s = json.dumps(obj, separators=(',', ':'))
                    if i < last_idx:
                        f.write(s + ',\n')
                    else:
                        f.write(s + ']')
        except Exception as e:
            print(f"[ERROR] Failed to write JSON: {e}")

    def write_xml(self, filename: str):
        try:
            with open(filename, 'w') as f:
                f.write('<?xml version="1.0" encoding="UTF-8"?>\n<dirble_scan>\n')
                for r in self.results:
                    f.write(f'<path url="{r.url}" code="{r.code}" content_len="{r.size}" '
                           f'is_directory="{str(r.is_directory).lower()}" '
                           f'is_listable="{str(r.is_listable).lower()}" '
                           f'redirect_url="{r.redirect_url}" '
                           f'found_from_listable="{str(r.found_from_listable).lower()}"/>\n')
                f.write('</dirble_scan>')
        except Exception as e:
            print(f"[ERROR] Failed to write XML: {e}")

    def write_txt(self, filename: str):
        try:
            with open(filename, 'w') as f:
                report = self.generate_text_report(False)
                f.write(report)
        except Exception as e:
            print(f"[ERROR] Failed to write TXT: {e}")


class Scanner:
    def __init__(self, args, wordlist: List[str], extensions: List[str],
                 prefixes: List[str], output: OutputManager):
        self.args = args
        self.wordlist = wordlist
        self.extensions = extensions
        self.prefixes = prefixes
        self.output = output
        self.max_threads = getattr(args, 'max_threads', 10)
        self.wordlist_split = getattr(args, 'wordlist_split', 3)
        self.scan_listable = getattr(args, 'scan_listable', False)
        self.scrape_listable = getattr(args, 'scrape_listable', False)
        self.disable_recursion = getattr(args, 'disable_recursion', False)
        self.max_recursion_depth = getattr(args, 'max_recursion_depth', None)
        self.force_extension = getattr(args, 'force_extension', False)
        self.ext_sub = getattr(args, 'ext_sub', False)
        self.show_htaccess = getattr(args, 'show_htaccess', False)
        self.disable_validator = getattr(args, 'disable_validator', False)
        self.scan_401 = getattr(args, 'scan_401', False)
        self.scan_403 = getattr(args, 'scan_403', False)

        # Build extension combos: None = no extension
        self.ext_combos: List[Optional[str]] = []
        if not self.force_extension:
            self.ext_combos.append(None)
        for ext in self.extensions:
            self.ext_combos.append(ext)

    def make_client(self) -> HTTPClient:
        return HTTPClient(self.args)

    def scan_all(self, uris: List[str]):
        """Scan all URIs"""
        detect_client = self.make_client()

        # Detection phase for all URIs
        uri_info = []  # (uri, base_url, detection)
        for uri in uris:
            base_url = normalize_to_dir(uri)
            display_url = uri

            detection = None
            if not self.disable_validator and not self.output.code_whitelist:
                probe_base = uri if uri.endswith('/') else base_url
                detection = detect_not_found(detect_client, probe_base)

                if detection.redirect_dest:
                    print_info(f"Detected nonexistent paths for {display_url} are (CODE:{detection.code}|DEST:{detection.redirect_dest})")
                else:
                    print_info(f"Detected nonexistent paths for {display_url} are (CODE:{detection.code})")

            uri_info.append((uri, base_url, detection))

        # Calculate initial split
        available = max(1, self.max_threads - 2)
        initial_split = max(available, self.wordlist_split)

        # Scan each URI
        first_uri = True
        for uri, base_url, detection in uri_info:
            if first_uri and initial_split > self.wordlist_split:
                print_info(f"Increasing wordlist-split for initial scan of {base_url} to {initial_split}")
            first_uri = False

            sub_dirs = self._scan_directory(
                base_url, detection, initial_split, depth=0,
                found_from_listable=False
            )

            # Recursively process subdirs
            self._process_subdirs(sub_dirs, depth=1)

    def _process_subdirs(self, subdirs: List[Dict], depth: int):
        for subdir in subdirs:
            url = subdir['url']

            if self.disable_recursion:
                continue
            if self.max_recursion_depth is not None and depth > self.max_recursion_depth:
                continue

            # Detect not-found for subdir
            detect_client = self.make_client()
            detection = None
            if not self.disable_validator and not self.output.code_whitelist:
                detection = detect_not_found(detect_client, url)
                if detection.redirect_dest:
                    print_info(f"Detected nonexistent paths for {url} are (CODE:{detection.code}|DEST:{detection.redirect_dest})")
                else:
                    print_info(f"Detected nonexistent paths for {url} are (CODE:{detection.code})")

            new_subdirs = self._scan_directory(
                url, detection, self.wordlist_split,
                depth=depth, found_from_listable=subdir['found_from_listable']
            )

            self._process_subdirs(new_subdirs, depth + 1)

    def _scan_directory(self, base_url: str, detection: Optional[NotFoundDetection],
                        split: int, depth: int, found_from_listable: bool) -> List[Dict]:
        """Scan a directory, return discovered subdirectories"""
        discovered = []
        discovered_lock = threading.Lock()

        handles = []

        for ext in self.ext_combos:
            chunks = self._split_wordlist(self.wordlist, split)

            for chunk in chunks:
                h = threading.Thread(
                    target=self._scan_chunk,
                    args=(base_url, ext, chunk, detection, discovered, discovered_lock,
                          depth, found_from_listable),
                    daemon=True
                )
                h.start()
                handles.append(h)

        for h in handles:
            h.join()

        return discovered

    def _scan_chunk(self, base_url: str, ext: Optional[str], words: List[str],
                    detection: Optional[NotFoundDetection],
                    discovered: List[Dict], discovered_lock: threading.Lock,
                    depth: int, found_from_listable: bool):
        """Scan a chunk of the wordlist"""
        client = self.make_client()

        print_debug(f"Scanning {base_url}")

        for word in words:
            # Handle %EXT% substitution
            if self.ext_sub:
                if ext is not None:
                    ext_no_dot = ext.lstrip('.')
                    if '%EXT%' in word:
                        final_word = word.replace('%EXT%', ext_no_dot)
                        final_ext = None  # ext already applied
                    else:
                        final_word = word
                        final_ext = ext
                else:
                    if '%EXT%' in word:
                        continue  # Skip %EXT% words when no extension
                    final_word = word
                    final_ext = None
            else:
                final_word = word
                final_ext = ext

            # Apply prefixes
            if self.prefixes:
                prefixed_words = [p + final_word for p in self.prefixes]
            else:
                prefixed_words = [final_word]

            for test_word in prefixed_words:
                if final_ext is None:
                    # No extension: check bare URL, then if not-found check directory URL
                    bare_url = base_url + test_word

                    bare_resp = client.request(bare_url, False)

                    if bare_resp is None:
                        # Network error - skip
                        continue

                    # Check if bare URL matches not-found
                    if detection and detection.matches(bare_resp):
                        print_trace_notfound(bare_url)
                        # Don't check directory version
                        continue

                    # Bare URL returned something interesting - also check directory version
                    dir_url = bare_url + '/'
                    dir_resp = client.request(dir_url, True)

                    if dir_resp is None:
                        # Bare URL was interesting but dir failed
                        # Report as file
                        self._emit_file(bare_url, bare_resp, detection, 
                                       discovered, discovered_lock, depth, found_from_listable)
                        continue

                    # Check if directory version matches not-found
                    if detection and detection.matches(dir_resp):
                        # Directory not found, but bare URL was interesting
                        self._emit_file(bare_url, bare_resp, detection,
                                       discovered, discovered_lock, depth, found_from_listable)
                    else:
                        # Directory found
                        body = dir_resp.get('body', '')
                        is_listing = bool(body) and is_directory_listing(body)
                        self._emit_dir(dir_url, dir_resp, is_listing,
                                      discovered, discovered_lock, depth, found_from_listable)
                else:
                    # Extension: just check as file
                    file_url = base_url + test_word + final_ext

                    resp = client.request(file_url, True)

                    if resp is None:
                        continue

                    if detection and detection.matches(resp):
                        print_trace_notfound(file_url)
                        continue

                    self._emit_file(file_url, resp, detection,
                                   discovered, discovered_lock, depth, found_from_listable)

        print_debug(f"Finished scanning {base_url}")

    def _emit_file(self, url: str, resp: Dict, detection: Optional[NotFoundDetection],
                   discovered: List[Dict], discovered_lock: threading.Lock,
                   depth: int, found_from_listable: bool):
        code = resp['code']
        size = resp['size']
        redirect_url = resp.get('redirect_url', '')

        # Filter 404 unless whitelisted or validator disabled
        if code == 404 and not self.output.code_whitelist and not self.disable_validator:
            return

        # Whitelist/blacklist
        if self.output.code_whitelist and code not in self.output.code_whitelist:
            return
        if code in self.output.code_blacklist:
            return

        # .ht* filter
        if code == 403 and not self.show_htaccess:
            path = url.rstrip('/')
            last_seg = path.rsplit('/', 1)[-1] if '/' in path else path
            if last_seg.startswith('.ht'):
                return

        result = ScanResult(url, code, size, False, False, redirect_url, found_from_listable)
        self.output.add_result(result)

    def _emit_dir(self, url: str, resp: Dict, is_listable: bool,
                  discovered: List[Dict], discovered_lock: threading.Lock,
                  depth: int, found_from_listable: bool):
        code = resp['code']
        size = resp['size']
        redirect_url = resp.get('redirect_url', '')
        body = resp.get('body', '')

        # Whitelist/blacklist
        if self.output.code_whitelist and code not in self.output.code_whitelist:
            return
        if code in self.output.code_blacklist:
            return

        result = ScanResult(url, code, size, True, is_listable, redirect_url, found_from_listable)
        self.output.add_result(result)

        # Determine if we should recurse
        should_scan = True
        if is_listable and not self.scan_listable:
            should_scan = False
        if code == 401 and not self.scan_401:
            should_scan = False
        if code == 403 and not self.scan_403:
            should_scan = False

        if should_scan and not self.disable_recursion:
            check_depth = self.max_recursion_depth is None or depth < self.max_recursion_depth
            if check_depth:
                with discovered_lock:
                    discovered.append({
                        'url': url,
                        'depth': depth + 1,
                        'found_from_listable': found_from_listable,
                        'is_listable': is_listable,
                    })

        # Scrape listable directory
        if is_listable and self.scrape_listable and body:
            scraped = scrape_urls_from_listing(body, url)
            for su in scraped:
                print_trace_code_detected(su, 0)
                if su.endswith('/') and not self.disable_recursion:
                    if self.max_recursion_depth is None or depth < self.max_recursion_depth:
                        with discovered_lock:
                            discovered.append({
                                'url': su,
                                'depth': depth + 1,
                                'found_from_listable': True,
                                'is_listable': False,
                            })

            # Also report listable items found from scraping
            for su in scraped:
                if not su.endswith('/'):
                    # Check if this URL is accessible
                    pass  # Skip actual checking for now

    def _split_wordlist(self, wordlist: List[str], n: int) -> List[List[str]]:
        n = max(1, n)
        chunks = [[] for _ in range(n)]
        for i, word in enumerate(wordlist):
            chunks[i % n].append(word)
        return chunks


def print_header(args, uris: List[str], wordlist_path: str,
                 prefixes: List[str], extensions: List[str]):
    print(f"Dirble {VERSION} (commit {COMMIT}, build {BUILD_DATE})")
    print("Developed by Izzy Whistlecroft")

    for uri in uris:
        target = normalize_to_dir(uri)
        print(f"Targets: {target}")

    print(f"Wordlists: {wordlist_path}")

    if prefixes:
        print(f"Prefixes: {' '.join(prefixes)}")
    else:
        print("No Prefixes")

    if extensions:
        print(f"Extensions: {' '.join(extensions)}")
    else:
        print("No Extensions")

    hide_lengths = parse_hide_lengths(getattr(args, 'hide_lengths', []))
    if hide_lengths:
        ranges_str = []
        for lo, hi in hide_lengths:
            if lo == hi:
                ranges_str.append(str(lo))
            else:
                ranges_str.append(f"{lo}-{hi}")
        print(f"Hidden lengths: [{', '.join(ranges_str)}]")
    else:
        print("No lengths hidden")

    print()


def main():
    global _verbose, _no_color

    parser = argparse.ArgumentParser(
        prog='dirble',
        description='Fast directory scanning and scraping tool',
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )

    parser.add_argument('uri_positional', nargs='?', metavar='uri')
    parser.add_argument('-u', '--uri', '--url', dest='uri', action='append', default=[])
    parser.add_argument('-U', '--uri-file', '--url-file', dest='uri_file')
    parser.add_argument('--verb', dest='verb', default='get')
    parser.add_argument('-w', '--wordlist', dest='wordlist')
    parser.add_argument('-p', '--prefixes', dest='prefixes', action='append', default=[])
    parser.add_argument('-P', '--prefix-file', dest='prefix_file')
    parser.add_argument('-x', '--extensions', dest='extensions', action='append', default=[])
    parser.add_argument('-X', '--extension-file', dest='extension_file')
    parser.add_argument('--ext-sub', dest='ext_sub', action='store_true')
    parser.add_argument('-f', '--force-extension', dest='force_extension', action='store_true')
    parser.add_argument('-k', '--ignore-cert', dest='ignore_cert', action='store_true')
    parser.add_argument('--show-htaccess', dest='show_htaccess', action='store_true')
    parser.add_argument('--timeout', dest='timeout', type=int, default=5)
    parser.add_argument('--max-errors', dest='max_errors', type=int, default=5)
    parser.add_argument('--json-file', '--oJ', dest='json_file')
    parser.add_argument('--no-color', dest='no_color', action='store_true')
    parser.add_argument('-o', '--output-file', '--oN', dest='output_file')
    parser.add_argument('--xml-file', '--oX', dest='xml_file')
    parser.add_argument('--hide-lengths', dest='hide_lengths', action='append', default=[])
    parser.add_argument('--output-all', '--oA', dest='output_all')
    parser.add_argument('--burp', dest='burp', action='store_true')
    parser.add_argument('--no-proxy', dest='no_proxy', action='store_true')
    parser.add_argument('--proxy', dest='proxy')
    parser.add_argument('-t', '--max-threads', dest='max_threads', type=int, default=10)
    parser.add_argument('-T', '--wordlist-split', dest='wordlist_split', type=int, default=3)
    parser.add_argument('-z', '--throttle', dest='throttle', type=int, default=None)
    parser.add_argument('--username', dest='username')
    parser.add_argument('--password', dest='password')
    parser.add_argument('-l', '--scan-listable', dest='scan_listable', action='store_true')
    parser.add_argument('--max-recursion-depth', dest='max_recursion_depth', type=int, default=None)
    parser.add_argument('-r', '--disable-recursion', dest='disable_recursion', action='store_true')
    parser.add_argument('--scrape-listable', dest='scrape_listable', action='store_true')
    parser.add_argument('-a', '--user-agent', dest='user_agent')
    parser.add_argument('-c', '--cookie', dest='cookies', action='append', default=[])
    parser.add_argument('-H', '--header', dest='header', action='append', default=[])
    parser.add_argument('-S', '--silent', dest='silent', action='store_true')
    parser.add_argument('-v', '--verbose', dest='verbose', action='count', default=0)
    parser.add_argument('-B', '--code-blacklist', dest='code_blacklist', action='append', default=[])
    parser.add_argument('--disable-validator', dest='disable_validator', action='store_true')
    parser.add_argument('-W', '--code-whitelist', dest='code_whitelist', action='append', default=[])
    parser.add_argument('--scan-401', dest='scan_401', action='store_true')
    parser.add_argument('--scan-403', dest='scan_403', action='store_true')
    parser.add_argument('-V', '--version', action='version',
                        version=f'Dirble {VERSION} (commit {COMMIT}, build {BUILD_DATE})')

    args = parser.parse_args()

    _verbose = args.verbose
    _no_color = args.no_color

    # Collect URIs
    uris = []
    if args.uri_positional:
        uris.append(args.uri_positional)
    uris.extend(args.uri or [])

    if args.uri_file:
        try:
            with open(args.uri_file) as f:
                for line in f:
                    line = line.strip()
                    if line:
                        uris.append(line)
        except IOError as e:
            print(f"[ERROR] Failed to open URI file: {e}")
            sys.exit(1)

    if not uris:
        parser.print_help()
        return

    # Load wordlist
    if args.wordlist:
        wordlist_path = args.wordlist
    else:
        exe_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
        default_path = os.path.join(exe_dir, 'dirble_wordlist.txt')
        if not os.path.exists(default_path):
            print("[ERROR] Unable to find default wordlist")
            sys.exit(1)
        wordlist_path = default_path

    try:
        with open(wordlist_path) as f:
            wordlist = [line.strip() for line in f if line.strip()]
    except IOError as e:
        print(f"[ERROR] Failed to open wordlist: {e}")
        sys.exit(1)

    # Process extensions (flatten comma-separated)
    extensions = []
    for ext_str in args.extensions:
        for ext in ext_str.split(','):
            ext = ext.strip()
            if ext:
                extensions.append(ext)
    if args.extension_file:
        try:
            with open(args.extension_file) as f:
                for line in f:
                    ext = line.strip()
                    if ext:
                        extensions.append(ext)
        except IOError as e:
            print(f"[ERROR] Failed to open extension file: {e}")
            sys.exit(1)

    # Process prefixes
    prefixes = []
    for pref_str in args.prefixes:
        for pref in pref_str.split(','):
            pref = pref.strip()
            if pref:
                prefixes.append(pref)
    if args.prefix_file:
        try:
            with open(args.prefix_file) as f:
                for line in f:
                    pref = line.strip()
                    if pref:
                        prefixes.append(pref)
        except IOError as e:
            print(f"[ERROR] Failed to open prefix file: {e}")
            sys.exit(1)

    # Flatten hide_lengths
    if args.hide_lengths:
        new_hide = []
        for item in args.hide_lengths:
            for part in item.split(','):
                new_hide.append(part.strip())
        args.hide_lengths = new_hide

    # Flatten code lists
    if args.code_blacklist:
        new_bl = []
        for item in args.code_blacklist:
            for part in item.split(','):
                new_bl.append(part.strip())
        args.code_blacklist = new_bl

    if args.code_whitelist:
        new_wl = []
        for item in args.code_whitelist:
            for part in item.split(','):
                new_wl.append(part.strip())
        args.code_whitelist = new_wl

    # Set up output files
    if args.output_all:
        json_file = f"{args.output_all}.json"
        xml_file = f"{args.output_all}.xml"
        txt_file = f"{args.output_all}.txt"
    else:
        json_file = getattr(args, 'json_file', None)
        xml_file = getattr(args, 'xml_file', None)
        txt_file = getattr(args, 'output_file', None)

    # Print header if tty
    if cached_is_tty():
        print_header(args, uris, wordlist_path, prefixes, extensions)

    # Set up output manager
    output = OutputManager(args, uris)

    # Run scanner
    scanner = Scanner(args, wordlist, extensions, prefixes, output)
    scanner.scan_all(uris)

    # Generate final output
    if cached_is_tty():
        report = output.generate_text_report(True)
        print()
        print(report, end='')

    if txt_file:
        output.write_txt(txt_file)

    if json_file:
        output.write_json(json_file)

    if xml_file:
        output.write_xml(xml_file)


if __name__ == '__main__':
    main()
