    result = []
    for item in items:
        for part in item.split(','):
            part = part.strip()
            if '-' in part:
                try:
                    lo, hi = part.split('-', 1)
                    result.append((int(lo), int(hi)))
                except ValueError:
                    pass
            else:
                try:
                    n = int(part)
                    result.append((n, n))
                except ValueError:
