        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            for k, v in attrs:
                if k == 'href' and v:
                    if v in ('/', '../') or v.startswith('#') or v.startswith('?'):
                        continue
                    if v.startswith('http://') or v.startswith('https://'):
                        self.links.append(v)
                    else:
                        try:
                            self.links.append(urllib.parse.urljoin(self.base_url, v))
                        except Exception:
                            pass


def is_dir_listing(body: str) -> bool:
    for pat in ["Index of /", "Directory listing for /", "<title>Directory listing",
                "Parent Directory", "[PARENTDIR]", "Directory Listing"]:
        if pat in body:
            return True
    return False


def scrape_listing(body: str, base_url: str) -> List[str]:
    p = DirListingParser(base_url)
    try:
        p.feed(body)
    except Exception:
        pass
    seen = set()
    result = []
    for link in p.links:
        if link not in seen:
            seen.add(link)
            result.append(link)
    return result


def normalize_dir(uri: str) -> str:
    if uri.endswith('/'):
        return uri
    parsed = urllib.parse.urlparse(uri)
    path = parsed.path
    if not path or path == '/':
        return urllib.parse.urlunparse((parsed.scheme, parsed.netloc, '/',
                                       parsed.params, parsed.query, parsed.fragment))
    parent = path.rsplit('/', 1)[0] + '/'
    if not parent or parent == '/':
        parent = '/'
    return urllib.parse.urlunparse((parsed.scheme, parsed.netloc, parent,
                                    parsed.params, parsed.query, parsed.fragment))


def display_uri(uri: str) -> str:
    """Get display form of URI for INFO messages"""
    parsed = urllib.parse.urlparse(uri)
    if not parsed.path or parsed.path == '/':
        # Just host - add slash
        return urllib.parse.urlunparse((parsed.scheme, parsed.netloc, '/',
                                       parsed.params, parsed.query, parsed.fragment))
    return uri


def parse_hide_lengths(items: List[str]) -> List[Tuple[int, int]]:
    result = []
    for item in items:
        for part in item.split(','):
            part = part.strip()
            if '-' in part:
                try:
                    lo, hi = part.split('-', 1)
                    result.append((int(lo), int(hi)))
                except ValueError:
                    pass
            else:
                try:
                    n = int(part)
                    result.append((n, n))
                except ValueError:
                    pass
    return result


def parse_codes(items: List[str]) -> List[int]:
    result = []
    for item in items:
        for part in item.split(','):
            try:
                result.append(int(part.strip()))
            except ValueError:
                pass
    return result


class HTTPClient:
    def __init__(self, args):
        self.timeout = getattr(args, 'timeout', 5)
        self.verb = getattr(args, 'verb', 'get').upper()
        self.user_agent = getattr(args, 'user_agent', None)
        self.cookies = list(getattr(args, 'cookies', []))
        self.custom_headers = list(getattr(args, 'header', []))
        self.ignore_cert = getattr(args, 'ignore_cert', False)
        self.no_proxy = getattr(args, 'no_proxy', False)
        self.throttle = getattr(args, 'throttle', None)
        self.username = getattr(args, 'username', None)
        self.password = getattr(args, 'password', None)
        self.proxy = None

        if getattr(args, 'burp', False):
            self.proxy = "http://localhost:8080"
        elif getattr(args, 'proxy', None):
            self.proxy = args.proxy

        self._ssl_ctx = ssl.create_default_context()
        if self.ignore_cert:
            self._ssl_ctx.check_hostname = False
            self._ssl_ctx.verify_mode = ssl.CERT_NONE

    def _make_opener(self):
        class NoRedir(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *args):
                return None

        handlers = [NoRedir(), urllib.request.HTTPSHandler(context=self._ssl_ctx)]
        if self.proxy and not self.no_proxy:
            handlers.append(urllib.request.ProxyHandler({'http': self.proxy, 'https': self.proxy}))
        elif self.no_proxy:
            handlers.append(urllib.request.ProxyHandler({}))

        return urllib.request.build_opener(*handlers)

    def request(self, url: str, get_body: bool = True) -> Optional[Dict]:
        print_trace_req(url)

        if self.throttle:
            time.sleep(self.throttle / 1000.0)

        # Extract credentials from URL if embedded
        parsed = urllib.parse.urlparse(url)
        username = parsed.username or self.username
        password = parsed.password or self.password

        if parsed.username or parsed.password:
            netloc = parsed.hostname or ''
            if parsed.port:
                netloc += f":{parsed.port}"
            clean_url = urllib.parse.urlunparse((parsed.scheme, netloc, parsed.path,
                                                 parsed.params, parsed.query, parsed.fragment))
        else:
            clean_url = url

        req = urllib.request.Request(clean_url, method=self.verb)

        if username:
            creds = base64.b64encode(f"{username}:{password or ''}".encode()).decode()
            req.add_header('Authorization', f'Basic {creds}')

        if self.user_agent:
            req.add_header('User-Agent', self.user_agent)

        if self.cookies:
            req.add_header('Cookie', '; '.join(self.cookies))

        for hdr in self.custom_headers:
            if ':' in hdr:
                name, _, val = hdr.partition(':')
                req.add_header(name.strip(), val.strip())

        opener = self._make_opener()

        try:
            with opener.open(req, timeout=self.timeout) as resp:
                code = resp.status
                cl_hdr = resp.headers.get('Content-Length')

                body = None
                if get_body and self.verb != 'HEAD':
                    raw = resp.read()
                    body = raw.decode('utf-8', errors='replace')
                    cl = int(cl_hdr) if cl_hdr else len(body)
                else:
                    resp.read()
                    cl = int(cl_hdr) if cl_hdr else 0

                return {'code': code, 'size': cl, 'redirect_url': '', 'body': body}

        except urllib.error.HTTPError as e:
            code = e.code
            cl_hdr = e.headers.get('Content-Length')
            redir = ''

            if 300 <= code <= 399:
                loc = e.headers.get('Location', '')
                if loc:
                    if loc.startswith(('http://', 'https://')):
                        redir = loc
                    else:
                        try:
                            redir = urllib.parse.urljoin(url, loc)
                        except Exception:
                            redir = loc

            body = None
            if get_body and self.verb != 'HEAD':
                try:
                    raw = e.read()
                    body = raw.decode('utf-8', errors='replace')
                    cl = int(cl_hdr) if cl_hdr else len(body)
                except Exception:
                    cl = 0
            else:
                try:
                    e.read()
                except Exception:
                    pass
                try:
                    cl = int(cl_hdr) if cl_hdr else 0
                except (ValueError, TypeError):
                    cl = 0

            return {'code': code, 'size': cl, 'redirect_url': redir, 'body': body}

        except Exception:
            return None


class NotFound:
    def __init__(self, code: int, dest: str = ""):
        self.code = code
        self.dest = dest

    def matches(self, resp: Dict) -> bool:
        if resp['code'] != self.code:
            return False
        if self.dest and resp.get('redirect_url', '') != self.dest:
            return False
        return True


def probe_not_found(client: HTTPClient, base_url: str) -> NotFound:
    codes = []
    dests = []
    for n in [10, 20, 30]:
        r = client.request(base_url + rand_str(n), False)
        if r:
            codes.append(r['code'])
            dests.append(r.get('redirect_url', ''))
        else:
            codes.append(0)
            dests.append('')

    code = Counter(codes).most_common(1)[0][0] if codes else 404

    dest = ""
    if 300 <= code <= 399:
        ne = [d for d in dests if d]
        if ne and all(d == ne[0] for d in ne):
            dest = ne[0]

    return NotFound(code, dest)


def is_direct_child(url: str, parent: str) -> bool:
    if not url.startswith(parent):
        return False
    rest = url[len(parent):]
    if url.endswith('/'):
        name = rest.rstrip('/')
        return '/' not in name and bool(name)
    else:
        return '/' not in rest and bool(rest)


def dfs_order(results: List[ScanResult], base_url: str) -> List[ScanResult]:
    """Sort results in DFS order: files before dirs at each level"""
    ordered = []

    def visit(url):
        files = [r for r in results if is_direct_child(r.url, url) and not r.is_directory and not r.is_listable]
        dirs = [r for r in results if is_direct_child(r.url, url) and (r.is_directory or r.is_listable)]
        ordered.extend(files)
        for d in dirs:
            ordered.append(d)
            visit(d.url)

    visit(base_url)
    return ordered


class OutputMgr:
    def __init__(self, args, uris: List[str]):
        self.args = args
        self.uris = uris
        self.results: List[ScanResult] = []
        self.lock = threading.Lock()
        self.hide_lengths = parse_hide_lengths(getattr(args, 'hide_lengths', []))
        self.code_bl = parse_codes(getattr(args, 'code_blacklist', []))
        self.code_wl = parse_codes(getattr(args, 'code_whitelist', []))

    def should_hide(self, r: ScanResult) -> bool:
        if self.code_wl and r.code not in self.code_wl:
            return True
        if r.code in self.code_bl:
            return True
        if not r.is_directory and not r.is_listable:
            for lo, hi in self.hide_lengths:
                if lo <= r.size <= hi:
                    return True
        return False

    def add(self, r: ScanResult):
        with self.lock:
            if not self.should_hide(r):
                if not _silent:
                    print(r.format_line())
            self.results.append(r)

    def make_report_for_uri(self, uri: str, use_indent: bool) -> str:
        base = normalize_dir(uri)
        indent = "  " if use_indent else ""
        nested_indent = "    " if use_indent else ""

        visible = [r for r in self.results if not self.should_hide(r) and r.url.startswith(base)]
        ordered = dfs_order(visible, base)

        out = f"Dirble Scan Report for {base}:\n"
        for r in ordered:
            if r.is_directory or r.is_listable:
                out += "\n"
                out += r.format_line(indent) + "\n" if not use_indent else r.format_line(indent) + "\n"
            else:
                out += r.format_line(indent) + "\n"
        out += "\n"
        return out

    def write_txt(self, filename: str):
        try:
            with open(filename, 'w') as f:
                for uri in self.uris:
                    f.write(self.make_report_for_uri(uri, False))
        except Exception as e:
            print(f"[ERROR] Failed to write TXT: {e}")

    def write_json(self, filename: str):
        try:
            with open(filename, 'w') as f:
                if not self.results:
                    f.write('[]')
                    return
                f.write('[')
                last = len(self.results) - 1
                for i, r in enumerate(self.results):
                    obj = {
                        "url": r.url, "code": r.code, "size": r.size,
                        "is_directory": r.is_directory, "is_listable": r.is_listable,
                        "redirect_url": r.redirect_url, "found_from_listable": r.found_from_listable,
                    }
                    s = json.dumps(obj, separators=(',', ':'))
                    if i < last:
                        f.write(s + ',\n')
                    else:
                        f.write(s + ']')
        except Exception as e:
            print(f"[ERROR] Failed to write JSON: {e}")

    def write_xml(self, filename: str):
        try:
            with open(filename, 'w') as f:
                f.write('<?xml version="1.0" encoding="UTF-8"?>\n<dirble_scan>\n')
                for r in self.results:
                    f.write(f'<path url="{r.url}" code="{r.code}" content_len="{r.size}" '
                           f'is_directory="{str(r.is_directory).lower()}" '
                           f'is_listable="{str(r.is_listable).lower()}" '
                           f'redirect_url="{r.redirect_url}" '
                           f'found_from_listable="{str(r.found_from_listable).lower()}"/>\n')
                f.write('</dirble_scan>')
        except Exception as e:
            print(f"[ERROR] Failed to write XML: {e}")


class Scanner:
    def __init__(self, args, wordlist, extensions, prefixes, output):
        self.args = args
        self.wordlist = wordlist
        self.extensions = extensions
        self.prefixes = prefixes
        self.output = output
        self.max_threads = getattr(args, 'max_threads', 10)
        self.split = getattr(args, 'wordlist_split', 3)
        self.scan_listable = getattr(args, 'scan_listable', False)
        self.scrape_listable = getattr(args, 'scrape_listable', False)
        self.disable_rec = getattr(args, 'disable_recursion', False)
        self.max_depth = getattr(args, 'max_recursion_depth', None)
        self.force_ext = getattr(args, 'force_extension', False)
        self.ext_sub = getattr(args, 'ext_sub', False)
        self.show_ht = getattr(args, 'show_htaccess', False)
        self.dis_val = getattr(args, 'disable_validator', False)
        self.scan_401 = getattr(args, 'scan_401', False)
        self.scan_403 = getattr(args, 'scan_403', False)

        self.ext_combos = []
        if not self.force_ext:
            self.ext_combos.append(None)
        for ext in self.extensions:
            self.ext_combos.append(ext)

    def new_client(self) -> HTTPClient:
        return HTTPClient(self.args)

    def scan_all(self, uris: List[str]):
        client = self.new_client()

        uri_data = []
        for uri in uris:
            base = normalize_dir(uri)
            disp = display_uri(uri)

            nf = None
            if not self.dis_val and not self.output.code_wl:
                probe = uri if uri.endswith('/') else base
                nf = probe_not_found(client, probe)
                if nf.dest:
                    print_info(f"Detected nonexistent paths for {disp} are (CODE:{nf.code}|DEST:{nf.dest})")
                else:
                    print_info(f"Detected nonexistent paths for {disp} are (CODE:{nf.code})")

            uri_data.append((uri, base, nf))

        avail = max(1, self.max_threads - 2)
        init_split = max(avail, self.split)

        first = True
        for uri, base, nf in uri_data:
            if first and init_split > self.split:
                print_info(f"Increasing wordlist-split for initial scan of {base} to {init_split}")
            first = False

            subdirs = self._scan_dir(base, nf, init_split, 0, False)
            self._recurse(subdirs, 1)

    def _recurse(self, subdirs: List[Dict], depth: int):
        for sd in subdirs:
            if self.disable_rec:
                continue
            if self.max_depth is not None and depth > self.max_depth:
                continue

            url = sd['url']
            client = self.new_client()

            nf = None
            if not self.dis_val and not self.output.code_wl:
                nf = probe_not_found(client, url)
                if nf.dest:
                    print_info(f"Detected nonexistent paths for {url} are (CODE:{nf.code}|DEST:{nf.dest})")
                else:
                    print_info(f"Detected nonexistent paths for {url} are (CODE:{nf.code})")

            new_subs = self._scan_dir(url, nf, self.split, depth, sd['from_listable'])
            self._recurse(new_subs, depth + 1)

    def _scan_dir(self, base: str, nf: Optional[NotFound], split: int,
                  depth: int, from_listable: bool) -> List[Dict]:
        disc = []
        disc_lock = threading.Lock()

        threads = []
        for ext in self.ext_combos:
            chunks = self._split(self.wordlist, split)
            for chunk in chunks:
                t = threading.Thread(
                    target=self._worker,
                    args=(base, ext, chunk, nf, disc, disc_lock, depth, from_listable),
                    daemon=True
                )
                t.start()
                threads.append(t)

        for t in threads:
            t.join()

        return disc

    def _worker(self, base: str, ext: Optional[str], words: List[str],
                nf: Optional[NotFound], disc: List[Dict], disc_lock: threading.Lock,
                depth: int, from_listable: bool):

        client = self.new_client()
        print_debug("dirble::request_thread", f"Scanning {base}")

        for word in words:
            # Handle %EXT% substitution
            if self.ext_sub:
                if ext is not None:
                    if '%EXT%' in word:
                        final_word = word.replace('%EXT%', ext.lstrip('.'))
                        final_ext = None
                    else:
                        final_word = word
                        final_ext = ext
                else:
                    if '%EXT%' in word:
                        continue
                    final_word = word
                    final_ext = None
            else:
                final_word = word
                final_ext = ext

            # Apply prefixes
            variants = [p + final_word for p in self.prefixes] if self.prefixes else [final_word]

            for vword in variants:
                if final_ext is None:
                    # No extension: check bare URL, if not-found check dir URL
                    bare = base + vword
                    bare_resp = client.request(bare, False)

                    if bare_resp is None:
                        continue

                    if nf and nf.matches(bare_resp):
                        print_trace_notfound(bare)
                        continue

                    # Bare URL is interesting - also check as directory
                    dir_url = bare + '/'
                    dir_resp = client.request(dir_url, True)

                    if dir_resp is None:
                        self._emit_file(bare, bare_resp, nf, disc, disc_lock, depth, from_listable, client)
                        continue

                    if nf and nf.matches(dir_resp):
                        # Dir not found, report bare as file
                        self._emit_file(bare, bare_resp, nf, disc, disc_lock, depth, from_listable, client)
                    else:
                        # Directory found
                        body = dir_resp.get('body') or ''
                        listing = bool(body) and is_dir_listing(body)
                        self._emit_dir(dir_url, dir_resp, listing, disc, disc_lock, depth, from_listable, body)
                else:
                    # Extension variant
                    file_url = base + vword + final_ext
                    resp = client.request(file_url, True)

                    if resp is None:
                        continue

                    if nf and nf.matches(resp):
                        print_trace_notfound(file_url)
                        continue

                    self._emit_file(file_url, resp, nf, disc, disc_lock, depth, from_listable, client)

        print_debug("dirble::request_thread", f"Finished scanning {base}")

    def _emit_file(self, url, resp, nf, disc, disc_lock, depth, from_listable, client):
        code, size, redir = resp['code'], resp['size'], resp.get('redirect_url', '')

        # Filter 404 unless whitelisted or validator disabled
        if code == 404 and not self.output.code_wl and not self.dis_val:
            return
        if self.output.code_wl and code not in self.output.code_wl:
            return
        if code in self.output.code_bl:
            return

        # .ht* filter
        if code == 403 and not self.show_ht:
            seg = url.rstrip('/').rsplit('/', 1)[-1]
            if seg.startswith('.ht'):
                return

        self.output.add(ScanResult(url, code, size, False, False, redir, from_listable))

    def _emit_dir(self, url, resp, listing, disc, disc_lock, depth, from_listable, body):
        code, size, redir = resp['code'], resp['size'], resp.get('redirect_url', '')

        if self.output.code_wl and code not in self.output.code_wl:
            return
        if code in self.output.code_bl:
            return

        self.output.add(ScanResult(url, code, size, True, listing, redir, from_listable))

        # Determine if we should recurse
        if self.disable_rec:
            return
        if listing and not self.scan_listable:
            should_recurse = False
        elif code == 401 and not self.scan_401:
            should_recurse = False
        elif code == 403 and not self.scan_403:
            should_recurse = False
        else:
            should_recurse = True

        if should_recurse:
            depth_ok = self.max_depth is None or depth < self.max_depth
            if depth_ok:
                with disc_lock:
                    disc.append({'url': url, 'depth': depth + 1, 'from_listable': from_listable})

        # Scrape listable directory
        if listing and self.scrape_listable and body:
            scraped = scrape_listing(body, url)
            for su in scraped:
                print_trace_code(su, 0)
                if su.endswith('/'):
                    depth_ok = self.max_depth is None or depth < self.max_depth
                    if not self.disable_rec and depth_ok:
                        with disc_lock:
                            disc.append({'url': su, 'depth': depth + 1, 'from_listable': True})

    @staticmethod
    def _split(words: List[str], n: int) -> List[List[str]]:
        n = max(1, n)
        chunks = [[] for _ in range(n)]
        for i, w in enumerate(words):
            chunks[i % n].append(w)
        return chunks


def print_header(args, uris, wl_path, prefixes, extensions):
    print(f"Dirble {VERSION} (commit {COMMIT}, build {BUILD_DATE})")
    print("Developed by Izzy Whistlecroft")
    for uri in uris:
        print(f"Targets: {normalize_dir(uri)}")
    print(f"Wordlists: {wl_path}")
    if prefixes:
        print(f"Prefixes: {' '.join(prefixes)}")
    else:
        print("No Prefixes")
    if extensions:
        print(f"Extensions: {' '.join(extensions)}")
    else:
        print("No Extensions")
    hl = parse_hide_lengths(getattr(args, 'hide_lengths', []))
    if hl:
        parts = [str(lo) if lo == hi else f"{lo}-{hi}" for lo, hi in hl]
        print(f"Hidden lengths: [{', '.join(parts)}]")
    else:
        print("No lengths hidden")
    print()


def main():
    global _silent, _verbose, _no_color, _use_tty

    p = argparse.ArgumentParser(prog='dirble', description='Fast directory scanning and scraping tool',
                                formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument('uri_positional', nargs='?', metavar='uri')
    p.add_argument('-u', '--uri', '--url', dest='uri', action='append', default=[])
    p.add_argument('-U', '--uri-file', '--url-file', dest='uri_file')
    p.add_argument('--verb', dest='verb', default='get', choices=['get', 'head', 'post'])
    p.add_argument('-w', '--wordlist', dest='wordlist')
    p.add_argument('-p', '--prefixes', dest='prefixes', action='append', default=[])
    p.add_argument('-P', '--prefix-file', dest='prefix_file')
    p.add_argument('-x', '--extensions', dest='extensions', action='append', default=[])
    p.add_argument('-X', '--extension-file', dest='extension_file')
    p.add_argument('--ext-sub', dest='ext_sub', action='store_true')
    p.add_argument('-f', '--force-extension', dest='force_extension', action='store_true')
    p.add_argument('-k', '--ignore-cert', dest='ignore_cert', action='store_true')
    p.add_argument('--show-htaccess', dest='show_htaccess', action='store_true')
    p.add_argument('--timeout', dest='timeout', type=int, default=5)
    p.add_argument('--max-errors', dest='max_errors', type=int, default=5)
    p.add_argument('--json-file', '--oJ', dest='json_file')
    p.add_argument('--no-color', dest='no_color', action='store_true')
    p.add_argument('-o', '--output-file', '--oN', dest='output_file')
    p.add_argument('--xml-file', '--oX', dest='xml_file')
    p.add_argument('--hide-lengths', dest='hide_lengths', action='append', default=[])
    p.add_argument('--output-all', '--oA', dest='output_all')
    p.add_argument('--burp', dest='burp', action='store_true')
    p.add_argument('--no-proxy', dest='no_proxy', action='store_true')
    p.add_argument('--proxy', dest='proxy')
    p.add_argument('-t', '--max-threads', dest='max_threads', type=int, default=10)
    p.add_argument('-T', '--wordlist-split', dest='wordlist_split', type=int, default=3)
    p.add_argument('-z', '--throttle', dest='throttle', type=int, default=None)
    p.add_argument('--username', dest='username')
    p.add_argument('--password', dest='password')
    p.add_argument('-l', '--scan-listable', dest='scan_listable', action='store_true')
    p.add_argument('--max-recursion-depth', dest='max_recursion_depth', type=int, default=None)
