    if args.code_blacklist:
        flat = []
        for item in args.code_blacklist:
            for part in item.split(','):
                flat.append(part.strip())
        args.code_blacklist = flat
    if args.code_whitelist:
        flat = []
        for item in args.code_whitelist:
            for part in item.split(','):
                flat.append(part.strip())
        args.code_whitelist = flat

    # Output files
    if args.output_all:
        json_f = f"{args.output_all}.json"
        xml_f = f"{args.output_all}.xml"
        txt_f = f"{args.output_all}.txt"
    else:
        json_f = getattr(args, 'json_file', None)
        xml_f = getattr(args, 'xml_file', None)
        txt_f = getattr(args, 'output_file', None)

    if _use_tty:
        print_header(args, uris, wl_path, prefixes, extensions)

    output = OutputMgr(args, uris)
