def color_code_str(code: int) -> str:
    global _no_color, _use_tty
    if _no_color or not _use_tty:
        return str(code)
    if 200 <= code <= 299:
        return f"{GREEN}{code}{RESET}"
    elif 300 <= code <= 399:
        return f"{CYAN}{code}{RESET}"
    elif 400 <= code <= 499:
        return f"{RED}{code}{RESET}"
    elif 500 <= code <= 599:
        return f"{YELLOW}{code}{RESET}"
    return str(code)

RAND_CHARS = string.ascii_letters + string.digits

def rand_str(n: int) -> str:
    return ''.join(random.choice(RAND_CHARS) for _ in range(n))


class ScanResult:
    __slots__ = ['url', 'code', 'size', 'is_directory', 'is_listable', 'redirect_url', 'found_from_listable']

    def __init__(self, url, code, size, is_directory, is_listable, redirect_url="", found_from_listable=False):
        self.url = url
        self.code = code
        self.size = size
        self.is_directory = is_directory
        self.is_listable = is_listable
        self.redirect_url = redirect_url
        self.found_from_listable = found_from_listable

    def format_line(self, indent="") -> str:
        code_str = color_code_str(self.code)
        dest = f"|DEST:{self.redirect_url}" if self.redirect_url else ""

        if self.is_listable:
